const BODY_PART_INJURY_KEYWORDS: Record<string, string[]> = {
  'плечо': ['плеч', 'дельт', 'ротатор', 'импинджмент', 'вращатель'],
  'колено': ['колен', 'мениск', 'пкс', 'связк колен', 'коленн'],
  'поясница': ['поясниц', 'спин', 'грыж', 'протруз', 'позвоноч'],
  'локоть': ['локт', 'эпикондилит', 'теннисн', 'локтев'],
  'запястье': ['запясть', 'кист', 'лучезапястн'],
  'грудь': ['груд', 'грудин', 'реберн'],
};

function detectInjuryZone(message: string, healthRestrictions?: Array<{ description: string; bodyPart: string }>): string[] {
  const zones: Set<string> = new Set();
  const text = message.toLowerCase();

  for (const [zone, keywords] of Object.entries(BODY_PART_INJURY_KEYWORDS)) {
    for (const kw of keywords) {
      if (text.includes(kw)) {
        zones.add(zone);
        break;
      }
    }
  }

  // Check stored health restrictions
  if (healthRestrictions) {
    for (const hr of healthRestrictions) {
      const r = `${hr.description} ${hr.bodyPart}`.toLowerCase();
      for (const [zone, keywords] of Object.entries(BODY_PART_INJURY_KEYWORDS)) {
        for (const kw of keywords) {
          if (r.includes(kw)) { zones.add(zone); break; }
        }
      }
    }
  }

  return Array.from(zones);
}

function getSubstitutionAdvice(injuryZones: string[]): string {
  if (injuryZones.length === 0) return '';

  const lines: string[] = ['\n## 🔄 ЗАМЕНЫ УПРАЖНЕНИЙ (с учётом ограничений)'];
  lines.push(`Зоны дискомфорта: ${injuryZones.join(', ')}`);

  for (const [exercise, sub] of Object.entries(EXERCISE_SUBSTITUTIONS)) {
    const affectedZones = sub.reason.split('/');
    if (affectedZones.some((z) => injuryZones.includes(z))) {
      lines.push(`- ❌ ${exercise} → ✅ ${sub.alternatives.slice(0, 2).join(' / ')}`);
    }
  }

  if (lines.length > 2) {
    lines.push('\n→ При создании тренировок/программ ИСПОЛЬЗУЙ замены из списка выше.');
    return lines.join('\n');
  }
  return '';
}

// ─── Block 13: Smart Follow-up Memory ───────────────────────────────────────

function detectPendingFollowups(history: Array<{ role: string; content: string | null }>): string[] {
  const followups: string[] = [];

  // Scan last 3 AI messages for unanswered questions
  const recentAiMessages = history
    .filter((m) => m.role === 'assistant' && m.content)
    .slice(-3);

  const recentUserMessages = history
    .filter((m) => m.role === 'user' && m.content)
    .slice(-3)
    .map((m) => (m.content || '').toLowerCase());

  for (const aiMsg of recentAiMessages) {
    const content = aiMsg.content || '';

    // Detect questions AI asked
    const questions = content.match(/[^.!?\n]*\?/g) || [];
    for (const q of questions) {
      const cleanQ = q.trim().toLowerCase();
      // Skip rhetorical questions
      if (cleanQ.includes('хочешь') || cleanQ.includes('хотите') || cleanQ.length < 15) continue;

      // Check if user answered this question in subsequent messages
      const keyWords = cleanQ
        .replace(/[?.,!]/g, '')
        .split(/\s+/)
        .filter((w) => w.length > 3)
        .slice(0, 3);

      const wasAnswered = recentUserMessages.some((userMsg) =>
        keyWords.some((kw) => userMsg.includes(kw))
      );

      if (!wasAnswered) {
        followups.push(q.trim());
      }
    }
  }

  return followups.slice(0, 2); // max 2 pending follow-ups
}

// ─── Block 14: Response Anti-Patterns Filter ────────────────────────────────

const BORING_OPENINGS = [
  /^(конечно|разумеется|безусловно|отличный вопрос|хороший вопрос|отличное решение|ок,?\s*давай)/i,
  /^(здравствуйте|добрый день),?\s*(рад|приятно)/i,
  /^(я\s*(бы\s*)?рекомендовал|позвольте\s*мне)/i,
  /^(как\s*ваш\s*(персональный\s*)?тренер)/i,
];

const GENERIC_PHRASES = [
  /важно\s*помнить,?\s*что/gi,
  /не\s*забывайте?\s*,?\s*что/gi,
  /стоит\s*отметить,?\s*что/gi,
  /в\s*первую\s*очередь/gi,
  /давайте?\s*разберёмся/gi,
  /хочу\s*подчеркнуть/gi,
];

function buildAntiPatternDirective(history: Array<{ role: string; content: string | null }>): string {
  // Check if AI has been repeating openings
  const lastAiMessages = history
    .filter((m) => m.role === 'assistant' && m.content)
    .slice(-3)
    .map((m) => m.content!);

  if (lastAiMessages.length < 2) return '';

  // Detect repeated first words/phrases
  const firstPhrases = lastAiMessages.map((msg) => {
    const firstLine = msg.split('\n')[0].trim().toLowerCase();
    return firstLine.split(/\s+/).slice(0, 3).join(' ');
  });

  const hasDuplicateOpening = new Set(firstPhrases).size < firstPhrases.length;

  const directives: string[] = [];

  if (hasDuplicateOpening) {
    directives.push('⚠️ РАЗНООБРАЗИЕ: Ты повторяешь одинаковые начала ответов. Начни ответ по-другому — сразу с сути, числа, действия или наблюдения из данных.');
  }

  // Check for generic filler phrases in last response
  const lastMsg = lastAiMessages[lastAiMessages.length - 1] || '';
  let genericCount = 0;
  for (const pattern of GENERIC_PHRASES) {
    if (pattern.test(lastMsg)) genericCount++;
    pattern.lastIndex = 0; // reset regex state
  }
  if (genericCount >= 2) {
    directives.push('⚠️ КОНКРЕТНОСТЬ: Предыдущий ответ содержал общие фразы-заполнители. Убери "важно помнить", "стоит отметить" и т.п. — сразу к фактам и числам.');
  }

  return directives.length > 0
    ? `\n\n## 🎯 КАЧЕСТВО ОТВЕТА\n${directives.join('\n')}`
    : '';
}

// ─── Block 15: AI Confidence & Uncertainty Handling ─────────────────────────

function getConfidenceDirective(user: any, message: string): string {
  const directives: string[] = [];

  // If user asks about medical/clinical things — lower confidence, recommend specialist
  const medicalPatterns = /(?:диагноз|лечени[ея]|лекарств|таблетк|уколы?|стероид|гормональн\s*тераpi|курс\s*(?:тест|стероид)|мрт|узи|рентген|анализ\s*(?:кров|мочи))/i;
  if (medicalPatterns.test(message)) {
    directives.push('⚠️ ОСТОРОЖНОСТЬ: Вопрос касается медицины. НЕ ставь диагнозы и НЕ назначай лечение. Дай общую информацию и ОБЯЗАТЕЛЬНО рекомендуй обратиться к спортивному врачу / эндокринологу / ортопеду.');
  }

  // If profile data is very incomplete — flag uncertainty in calculations
  const missingCritical = [];
  if (!user?.weightKg) missingCritical.push('вес');
  if (!user?.heightCm) missingCritical.push('рост');
  if (!user?.goal) missingCritical.push('цель');
  if (!user?.gender) missingCritical.push('пол');

  if (missingCritical.length >= 2) {
    directives.push(`⚠️ НЕПОЛНЫЕ ДАННЫЕ: Не хватает: ${missingCritical.join(', ')}. Любые расчёты (КБЖУ, программа) будут приблизительными — СКАЖИ ОБ ЭТОМ и попроси заполнить профиль.`);
  }

  // If user mentions contradictory goals
  const contradictions = [
    { pattern: /(?:похуде|сушк|дефицит).*(?:набр|масс|объём)/i, msg: 'Пользователь говорит одновременно про похудение и набор массы — уточни приоритет.' },
    { pattern: /(?:не\s*ем|голода|0\s*калорий).*(?:масс|сил|рос)/i, msg: 'Пользователь хочет расти но не ест — объясни почему это невозможно.' },
  ];
  for (const c of contradictions) {
    if (c.pattern.test(message)) {
      directives.push(`⚠️ ПРОТИВОРЕЧИЕ: ${c.msg}`);
    }
  }

  return directives.length > 0
    ? `\n\n## ⚖️ УВЕРЕННОСТЬ И ОГРАНИЧЕНИЯ\n${directives.join('\n')}`
    : '';
}

// ─── Block 16: Smart Workout Recommendation ─────────────────────────────────

function getWorkoutRecommendation(
  weekPlan: Record<string, any> | undefined,
  recentWorkouts: Array<{ name: string; completedAt: Date | null }>,
  dayOfWeek: number, // 0=Sun ... 6=Sat
): string {
  // dayOfWeek from JS: 0=Sun, but weekPlan uses 0=Mon...6=Sun
  const planDay = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
  const today = weekPlan?.[planDay];

  if (!today) return '';

  // Check if user already trained today
  const todayStr = new Date().toISOString().split('T')[0];
  const trainedToday = recentWorkouts.some(
    (w) => w.completedAt && w.completedAt.toISOString().split('T')[0] === todayStr
  );

  if (trainedToday) {
    return `\n\n## 📅 ТРЕНИРОВКА ДНЯ\nПо плану сегодня: ${today.emoji || '💪'} ${today.name} — уже выполнена ✅. Отдыхай или сделай лёгкую заминку/кардио.`;
  }

  // Check what was trained yesterday to avoid same muscle groups
  const yesterday = recentWorkouts.find((w) => {
    if (!w.completedAt) return false;
    const d = new Date(w.completedAt);
    const diff = Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60 * 24));
    return diff === 1;
  });

  let fatigueTip = '';
  if (yesterday) {
    fatigueTip = ` Вчера: ${yesterday.name} — учитывай усталость этих мышечных групп.`;
  }

  return `\n\n## 📅 ТРЕНИРОВКА ДНЯ\nПо плану сегодня: ${today.emoji || '💪'} **${today.name}**.${fatigueTip} Если пользователь спросит "что делать сегодня" — предложи эту тренировку.`;
}

// ─── Block 17: Nutrition Timing Intelligence ────────────────────────────────

function getNutritionTimingAdvice(
  hour: number,
  todayMeals: Array<{ type: string; totalCalories: number; totalProtein: number; createdAt: Date }>,
  recentWorkouts: Array<{ completedAt: Date | null }>,
  nutritionTargets?: { calories: number; protein: number } | null,
): string {
  const lines: string[] = [];

  // Check if workout is coming (planned for today) or just finished
  const todayStr = new Date().toISOString().split('T')[0];
  const trainedToday = recentWorkouts.some(
    (w) => w.completedAt && w.completedAt.toISOString().split('T')[0] === todayStr
  );

  // Post-workout window (trained today, less than 2h ago)
  const recentTraining = recentWorkouts.find((w) => {
    if (!w.completedAt) return false;
    const hoursAgo = (Date.now() - new Date(w.completedAt).getTime()) / (1000 * 60 * 60);
    return hoursAgo < 2;
  });

  if (recentTraining) {
    const postWorkoutMeal = todayMeals.find((m) => {
      const mealTime = new Date(m.createdAt).getTime();
      const workoutTime = new Date(recentTraining.completedAt!).getTime();
      return mealTime > workoutTime;
    });

    if (!postWorkoutMeal) {
      lines.push('🍽️ ПОСТ-ТРЕНИРОВКА: Прошло менее 2ч после тренировки и нет приёма пищи. Рекомендуй: 30-40г белка + быстрые углеводы (рис, банан, протеин с молоком).');
    }
  }

  // Meal timing gaps (>5 hours between meals)
  if (todayMeals.length >= 2) {
    const sortedMeals = [...todayMeals].sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
    for (let i = 1; i < sortedMeals.length; i++) {
      const gap = (new Date(sortedMeals[i].createdAt).getTime() - new Date(sortedMeals[i - 1].createdAt).getTime()) / (1000 * 60 * 60);
      if (gap > 5) {
        lines.push(`⏰ Перерыв ${Math.round(gap)}ч между приёмами пищи — слишком долго. Оптимально: каждые 3-4ч.`);
        break;
      }
    }
  }

  // Evening protein check
  if (hour >= 20 && nutritionTargets) {
    const totalProt = todayMeals.reduce((s, m) => s + m.totalProtein, 0);
    const remaining = nutritionTargets.protein - totalProt;
    if (remaining > 30) {
      lines.push(`🌙 Вечер, а до нормы белка ещё ${Math.round(remaining)}г. Рекомендуй казеин / творог перед сном.`);
    }
  }

  // Pre-workout timing
  if (!trainedToday && hour >= 15 && hour <= 20) {
    const lastMeal = todayMeals[todayMeals.length - 1];
    if (lastMeal) {
      const hoursSinceLastMeal = (Date.now() - new Date(lastMeal.createdAt).getTime()) / (1000 * 60 * 60);
      if (hoursSinceLastMeal > 3) {
        lines.push('⚡ Если тренировка вечером — стоит перекусить за 1-1.5ч: банан + немного белка.');
      }
    }
  }

  if (lines.length === 0) return '';
  return '\n\n## ⏱️ ТАЙМИНГ ПИТАНИЯ\n' + lines.join('\n');
}

// ─── Block 18: Progressive Overload Tracker ─────────────────────────────────

interface OverloadStatus {
  exercise: string;
  status: 'progressing' | 'plateau' | 'regressing';
  lastWeights: number[];
  suggestion: string;
}

function analyzeProgressiveOverload(
  exerciseSets: Array<{
    exercise: { name: string };
    workout: { completedAt: Date | null };
    sets: Array<{ weight: number | null; reps: number | null }>;
  }>
): OverloadStatus[] {
  // Group by exercise, get max weight per workout, sorted by date
  const exerciseHistory = new Map<string, Array<{ date: Date; maxWeight: number; maxReps: number }>>();

  for (const we of exerciseSets) {
    if (!we.workout.completedAt || we.sets.length === 0) continue;
    const name = we.exercise.name;
    const maxSet = we.sets.reduce((best, s) =>
      (s.weight || 0) > (best.weight || 0) ? s : best, we.sets[0]);

    if (!exerciseHistory.has(name)) exerciseHistory.set(name, []);
    exerciseHistory.get(name)!.push({
      date: we.workout.completedAt,
      maxWeight: maxSet.weight || 0,
      maxReps: maxSet.reps || 0,
    });
  }

  const results: OverloadStatus[] = [];

  for (const [exercise, history] of exerciseHistory) {
    if (history.length < 3) continue; // need at least 3 data points

    // Sort by date ascending
    history.sort((a, b) => a.date.getTime() - b.date.getTime());
    const last3 = history.slice(-3);
    const weights = last3.map((h) => h.maxWeight);

    let status: 'progressing' | 'plateau' | 'regressing';
    let suggestion: string;

    if (weights[2] > weights[0] && weights[2] > weights[1]) {
      status = 'progressing';
      suggestion = `${exercise}: прогрессия ✅ (${weights.join(' → ')} кг)`;
    } else if (Math.abs(weights[2] - weights[0]) <= 2.5 && Math.abs(weights[1] - weights[0]) <= 2.5) {
      status = 'plateau';
      suggestion = `${exercise}: ПЛАТО ⚠️ (${weights[0]} кг × 3 тренировки). Варианты: +микронагрузка 1.25кг, смена диапазона повторений, пауза-рест, или замена на аналог.`;
    } else if (weights[2] < weights[0]) {
      status = 'regressing';
      suggestion = `${exercise}: РЕГРЕСС ⛔ (${weights.join(' → ')} кг). Возможно: недовосстановление, недоедание, или нужен deload.`;
    } else {
      continue; // mixed, skip
    }

    results.push({ exercise, status, lastWeights: weights, suggestion });
  }

  return results;
}

function buildOverloadContext(overloadData: OverloadStatus[]): string {
  if (overloadData.length === 0) return '';

  const plateaus = overloadData.filter((o) => o.status === 'plateau');
  const regressions = overloadData.filter((o) => o.status === 'regressing');
  const progressions = overloadData.filter((o) => o.status === 'progressing');

  if (plateaus.length === 0 && regressions.length === 0 && progressions.length === 0) return '';

  const lines: string[] = ['\n## 📊 ПРОГРЕССИВНАЯ ПЕРЕГРУЗКА'];

  if (progressions.length > 0) {
    lines.push(`✅ Прогресс: ${progressions.slice(0, 3).map((p) => p.suggestion).join('; ')}`);
  }
  if (plateaus.length > 0) {
    lines.push(`⚠️ Плато: ${plateaus.map((p) => p.suggestion).join('\n')}`);
    lines.push('→ Если пользователь спрашивает про прогресс — обязательно упомяни плато и предложи решение.');
  }
  if (regressions.length > 0) {
    lines.push(`⛔ Регресс: ${regressions.map((r) => r.suggestion).join('\n')}`);
    lines.push('→ ОБЯЗАТЕЛЬНО обрати внимание на регресс и предложи причины + решения.');
  }

  return lines.join('\n');
}

// ─── Block 19: Recovery Score Estimation ────────────────────────────────────

function estimateRecoveryScore(
  recentWorkouts: Array<{ completedAt: Date | null; exercises: Array<{ sets: Array<{ completed: boolean }> }> }>,
  bodyWeightHistory: Array<{ weightKg: number; date: Date }>,
  todayMeals: Array<{ totalCalories: number; totalProtein: number }>,
  nutritionTargets?: { calories: number; protein: number } | null,
): { score: number; factors: string[] } {
  let score = 100; // start at 100, subtract for negative factors
  const factors: string[] = [];

  // Factor 1: Training frequency last 7 days
  const weekAgo = new Date();
  weekAgo.setDate(weekAgo.getDate() - 7);
  const weekSessions = recentWorkouts.filter(
    (w) => w.completedAt && new Date(w.completedAt) >= weekAgo
  ).length;

  if (weekSessions >= 6) {
    score -= 25;
    factors.push('Высокая частота тренировок (6+ за неделю) — риск перетренированности');
  } else if (weekSessions >= 5) {
    score -= 10;
    factors.push('5 тренировок за неделю — на грани');
  }

  // Factor 2: Training in last 24h
  const oneDayAgo = new Date();
  oneDayAgo.setDate(oneDayAgo.getDate() - 1);
  const trainedRecently = recentWorkouts.some(
    (w) => w.completedAt && new Date(w.completedAt) >= oneDayAgo
  );
  if (trainedRecently) {
    score -= 15;
    factors.push('Тренировка менее 24ч назад');
  }

  // Factor 3: Consecutive training days
  let consecutiveDays = 0;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let i = 0; i < 7; i++) {
    const checkDate = new Date(today);
    checkDate.setDate(checkDate.getDate() - i);
    const dateStr = checkDate.toISOString().split('T')[0];
    const trained = recentWorkouts.some(
      (w) => w.completedAt && w.completedAt.toISOString().split('T')[0] === dateStr
    );
    if (trained) consecutiveDays++;
    else break;
  }
  if (consecutiveDays >= 4) {
    score -= 20;
    factors.push(`${consecutiveDays} дней подряд без отдыха`);
  }

  // Factor 4: Nutrition quality (if data available)
  if (nutritionTargets && todayMeals.length > 0) {
    const totalProt = todayMeals.reduce((s, m) => s + m.totalProtein, 0);
    const totalCal = todayMeals.reduce((s, m) => s + m.totalCalories, 0);
    if (totalProt < nutritionTargets.protein * 0.6) {
      score -= 10;
      factors.push('Низкое потребление белка');
    }
    if (totalCal < nutritionTargets.calories * 0.7) {
      score -= 10;
      factors.push('Недобор калорий');
    }
  }

  // Factor 5: Weight fluctuation (stress indicator)
  if (bodyWeightHistory.length >= 3) {
    const last3 = bodyWeightHistory.slice(0, 3).map((bw) => bw.weightKg);
    const variance = Math.max(...last3) - Math.min(...last3);
    if (variance > 2) {
      score -= 10;
      factors.push(`Сильные колебания веса (±${variance.toFixed(1)} кг за 3 взвешивания)`);
    }
  }

  return { score: Math.max(0, Math.min(100, score)), factors };
}

function buildRecoveryContext(recovery: { score: number; factors: string[] }): string {
  if (recovery.score >= 80 && recovery.factors.length === 0) return '';

  const emoji = recovery.score >= 70 ? '🟢' : recovery.score >= 40 ? '🟡' : '🔴';
  const status = recovery.score >= 70 ? 'Хорошее восстановление' : recovery.score >= 40 ? 'Умеренная усталость' : 'Высокая усталость';

  const lines: string[] = [
    `\n## 🔋 ОЦЕНКА ВОССТАНОВЛЕНИЯ`,
    `${emoji} Score: ${recovery.score}/100 — ${status}`,
  ];

  if (recovery.factors.length > 0) {
    lines.push('Факторы:');
    for (const f of recovery.factors) {
      lines.push(`- ${f}`);
    }
  }

  if (recovery.score < 40) {
    lines.push('→ ОБЯЗАТЕЛЬНО рекомендуй лёгкий день или полный отдых. Не предлагай тяжёлых тренировок.');
  } else if (recovery.score < 70) {
    lines.push('→ Рекомендуй снизить интенсивность или объём. Упомяни важность сна и питания.');
  }

  return lines.join('\n');
}

// ─── Block 24: AI Memory — cross-session preference learning ────────────────

interface MemoryExtraction {
  category: string;
  key: string;
  value: string;
  confidence: number;
  source: 'stated' | 'inferred';
}

// Patterns to extract user preferences/facts from messages
const MEMORY_PATTERNS: Array<{ regex: RegExp; category: string; key: string; extract: (match: RegExpMatchArray) => string }> = [
  // Training schedule
  { regex: /тренируюсь?\s*(\d)\s*(раз|дн)/i, category: 'schedule', key: 'training_frequency', extract: (m) => `${m[1]} раз в неделю` },
  { regex: /по\s*(понедельник|вторник|сред|четверг|пятниц|суббот|воскресень)/i, category: 'schedule', key: 'training_days', extract: (m) => m[0] },
  // Equipment
  { regex: /(?:занимаюсь|тренируюсь)\s*(дома|в зале|на улице)/i, category: 'preference', key: 'training_location', extract: (m) => m[1] },
  { regex: /(?:у меня|есть|имеется)\s*(гантел|штанг|турник|брусья|гир|тренажёр|тренажер|резинк)/i, category: 'preference', key: 'available_equipment', extract: (m) => m[1] },
  // Diet preferences
  { regex: /(?:я\s+)?(вегетарианец|веган|не ем мясо|не ем рыб|не пью молок|без глютен|безлактозн)/i, category: 'allergy', key: 'diet_restriction', extract: (m) => m[1] },
  { regex: /(?:аллерги[яю]|непереносимость)\s+(?:на\s+)?([\wа-яА-Я]+)/i, category: 'allergy', key: 'food_allergy', extract: (m) => m[1] },
  // Injuries and limitations
  { regex: /(?:у меня|имеется|была?)\s*(грыж|протрузи|сколиоз|артрит|артроз)/i, category: 'injury', key: 'chronic_condition', extract: (m) => m[1] },
  { regex: /(?:болит|травмирова|проблемы с)\s*(плеч|колен|поясниц|спин|шей|локт|запясть|голеностоп)/i, category: 'injury', key: 'pain_area', extract: (m) => m[1] },
  // Preferences
  { regex: /(?:люблю|нравится|предпочитаю)\s*(присед|жим|тяг|кардио|йог|бег|плаван)/i, category: 'preference', key: 'favorite_exercise', extract: (m) => m[1] },
  { regex: /(?:не люблю|ненавижу|не хочу делать)\s*(кардио|присед|бег|планк)/i, category: 'preference', key: 'disliked_exercise', extract: (m) => m[1] },
  // Sleep pattern
  { regex: /(?:сплю|ложусь)\s*(?:в|около)?\s*(\d{1,2})[:\.]?(\d{2})?\s*(?:час|ночи)?/i, category: 'habit', key: 'sleep_time', extract: (m) => `${m[1]}:${m[2] || '00'}` },
  { regex: /(?:встаю|просыпаюсь)\s*(?:в|около)?\s*(\d{1,2})[:\.]?(\d{2})?/i, category: 'habit', key: 'wake_time', extract: (m) => `${m[1]}:${m[2] || '00'}` },
  // Experience
  { regex: /(?:занимаюсь|тренируюсь)\s*(?:уже)?\s*(\d+)\s*(лет|год|месяц)/i, category: 'preference', key: 'experience_stated', extract: (m) => `${m[1]} ${m[2]}` },
];

/**
 * Extract memorable facts from a user message.
 */
function extractMemories(message: string): MemoryExtraction[] {
  const memories: MemoryExtraction[] = [];

  for (const pattern of MEMORY_PATTERNS) {
    const match = message.match(pattern.regex);
    if (match) {
      memories.push({
        category: pattern.category,
        key: pattern.key,
        value: pattern.extract(match),
        confidence: 0.7, // stated explicitly
        source: 'stated',
      });
    }
  }

  return memories;
}

/**
 * Save or update extracted memories in the database.
 * Upsert: if key exists, increase confidence; if new, create.
 */
async function saveMemories(userId: string, memories: MemoryExtraction[]): Promise<void> {
  for (const mem of memories) {
    try {
      const existing = await prisma.aIMemory.findUnique({
        where: { userId_key: { userId, key: mem.key } },
      });

      if (existing) {
        // If same value, boost confidence; if different, update with reset confidence
        const sameValue = existing.value === mem.value;
        await prisma.aIMemory.update({
          where: { userId_key: { userId, key: mem.key } },
          data: {
            value: mem.value,
            confidence: sameValue
              ? Math.min(1.0, existing.confidence + 0.15)
              : mem.confidence,
            source: mem.source,
          },
        });
      } else {
        await prisma.aIMemory.create({
          data: {
            userId,
            category: mem.category,
            key: mem.key,
            value: mem.value,
            confidence: mem.confidence,
            source: mem.source,
          },
        });
      }
    } catch (e) {
      // Silently skip if DB issue (table may not exist yet)
      console.error('AIMemory save error:', e);
    }
  }
}

/**
 * Build context string from stored AI memories for injection into system prompt.
 */
async function getMemoryContext(userId: string): Promise<string> {
  try {
    const memories = await prisma.aIMemory.findMany({
      where: { userId, confidence: { gte: 0.5 } },
      orderBy: { confidence: 'desc' },
      take: 20,
    });

    if (memories.length === 0) return '';

    const grouped: Record<string, string[]> = {};
    for (const m of memories) {
      const cat = m.category;
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(`${m.key}: ${m.value} (${Math.round(m.confidence * 100)}%)`);
    }

    const lines: string[] = ['\n## 🧠 ПАМЯТЬ О ПОЛЬЗОВАТЕЛЕ (из прошлых разговоров)'];

    const categoryLabels: Record<string, string> = {
      preference: 'Предпочтения',
      habit: 'Привычки',
      injury: 'Травмы/ограничения',
      allergy: 'Аллергии/диета',
      schedule: 'Расписание',
      personality: 'Особенности',
    };

    for (const [cat, items] of Object.entries(grouped)) {
      lines.push(`**${categoryLabels[cat] || cat}:** ${items.join('; ')}`);
    }

    lines.push('→ Используй эту информацию для персонализации. Не переспрашивай то, что уже знаешь. Если информация противоречит текущему сообщению — уточни, не игнорируй.');

    return lines.join('\n');
  } catch {
    return '';
  }
}

// ─── Block 27: Muscle Balance Analysis ─────────────────────────────────────

// Map exercises to primary muscle groups
const EXERCISE_MUSCLE_MAP: Record<string, string[]> = {
  // Push
  'жим лёжа': ['грудь', 'трицепс', 'плечи-передние'],
  'жим лежа': ['грудь', 'трицепс', 'плечи-передние'],
  'жим штанги': ['грудь', 'трицепс', 'плечи-передние'],
  'жим гантелей': ['грудь', 'трицепс', 'плечи-передние'],
  'жим на наклонной': ['грудь-верх', 'трицепс', 'плечи-передние'],
  'отжимания': ['грудь', 'трицепс'],
  'жим стоя': ['плечи', 'трицепс'],
  'жим сидя': ['плечи', 'трицепс'],
  'армейский жим': ['плечи', 'трицепс'],
  'разведение гантелей': ['грудь'],
  'махи гантелями': ['плечи-средние'],
  'французский жим': ['трицепс'],
  'разгибание на блоке': ['трицепс'],
  // Pull
  'подтягивания': ['спина-широчайшие', 'бицепс'],
  'тяга верхнего блока': ['спина-широчайшие', 'бицепс'],
  'тяга штанги в наклоне': ['спина', 'бицепс'],
  'тяга гантели в наклоне': ['спина', 'бицепс'],
  'тяга нижнего блока': ['спина'],
  'становая тяга': ['спина', 'ягодицы', 'бёдра-задние'],
  'сгибания на бицепс': ['бицепс'],
  'молотки': ['бицепс', 'предплечья'],
  'шраги': ['трапеции'],
  // Legs
  'приседания': ['квадрицепс', 'ягодицы'],
  'приседания со штангой': ['квадрицепс', 'ягодицы', 'кор'],
  'жим ногами': ['квадрицепс', 'ягодицы'],
  'выпады': ['квадрицепс', 'ягодицы'],
  'румынская тяга': ['бёдра-задние', 'ягодицы'],
  'сгибание ног': ['бёдра-задние'],
  'разгибание ног': ['квадрицепс'],
  'подъём на носки': ['икры'],
  'ягодичный мост': ['ягодицы'],
  'гиперэкстензия': ['поясница', 'бёдра-задние'],
  // Core
  'планка': ['кор'],
  'скручивания': ['пресс'],
  'подъём ног': ['пресс-нижний'],
};

const MUSCLE_GROUPS_PUSH = ['грудь', 'грудь-верх', 'плечи', 'плечи-передние', 'плечи-средние', 'трицепс'];
const MUSCLE_GROUPS_PULL = ['спина', 'спина-широчайшие', 'бицепс', 'трапеции', 'предплечья'];
const MUSCLE_GROUPS_LEGS = ['квадрицепс', 'ягодицы', 'бёдра-задние', 'икры'];

interface MuscleBalanceResult {
  pushPullRatio: number; // ideal ~1.0
  upperLowerRatio: number; // ideal ~1.0-1.5
  neglectedMuscles: string[];
  overtrainedMuscles: string[];
  advice: string;
}

function analyzeMuscleBalance(
  exerciseSets: Array<{ exercise: { name: string }; sets: Array<{ weight: number | null; reps: number | null }> }>,
): MuscleBalanceResult {
  const muscleVolume: Record<string, number> = {};

  for (const es of exerciseSets) {
    const name = es.exercise.name.toLowerCase();
    let muscles: string[] = [];

    // Find matching muscle group
    for (const [exerciseName, groups] of Object.entries(EXERCISE_MUSCLE_MAP)) {
      if (name.includes(exerciseName) || exerciseName.includes(name)) {
        muscles = groups;
        break;
      }
    }

    if (muscles.length === 0) continue;

    // Count total volume (sets * reps * weight) per muscle
    const totalVol = es.sets.reduce((sum, s) => {
      return sum + ((s.weight || 0) * (s.reps || 0));
    }, 0);

    const volPerMuscle = totalVol / muscles.length;
    for (const m of muscles) {
      muscleVolume[m] = (muscleVolume[m] || 0) + volPerMuscle;
    }
  }

  // Calculate push/pull ratio
  const pushVol = MUSCLE_GROUPS_PUSH.reduce((s, m) => s + (muscleVolume[m] || 0), 0);
  const pullVol = MUSCLE_GROUPS_PULL.reduce((s, m) => s + (muscleVolume[m] || 0), 0);
  const upperVol = pushVol + pullVol;
  const lowerVol = MUSCLE_GROUPS_LEGS.reduce((s, m) => s + (muscleVolume[m] || 0), 0);

  const pushPullRatio = pullVol > 0 ? pushVol / pullVol : pushVol > 0 ? 5.0 : 1.0;
  const upperLowerRatio = lowerVol > 0 ? upperVol / lowerVol : upperVol > 0 ? 5.0 : 1.0;

  // Detect neglected muscles (0 volume)
  const allMuscles = [...MUSCLE_GROUPS_PUSH, ...MUSCLE_GROUPS_PULL, ...MUSCLE_GROUPS_LEGS];
  const neglectedMuscles = allMuscles.filter((m) => !muscleVolume[m] || muscleVolume[m] === 0);

  // Detect overtrained (>3x average)
  const volumes = Object.values(muscleVolume).filter((v) => v > 0);
  const avgVol = volumes.length > 0 ? volumes.reduce((a, b) => a + b, 0) / volumes.length : 0;
  const overtrainedMuscles = Object.entries(muscleVolume)
    .filter(([, vol]) => vol > avgVol * 3)
    .map(([m]) => m);

  // Build advice
  const adviceParts: string[] = [];
  if (pushPullRatio > 1.5) {
    adviceParts.push(`Много жимовых (push:pull = ${pushPullRatio.toFixed(1)}). Добавь тяговые: подтягивания, тяга в наклоне, фейспулл.`);
  } else if (pushPullRatio < 0.7) {
    adviceParts.push(`Мало жимовых (push:pull = ${pushPullRatio.toFixed(1)}). Добавь жим, отжимания, разводки.`);
  }
  if (upperLowerRatio > 2.0) {
    adviceParts.push(`Перекос в верх тела (верх:низ = ${upperLowerRatio.toFixed(1)}). Добавь приседания, выпады, румынскую тягу.`);
  } else if (upperLowerRatio < 0.5) {
    adviceParts.push(`Много ног, мало верха (верх:низ = ${upperLowerRatio.toFixed(1)}). Баланс по верху: жим, тяги, подтягивания.`);
  }

  const importantNeglected = neglectedMuscles.filter((m) =>
    ['спина', 'ягодицы', 'бёдра-задние', 'плечи-средние', 'икры'].includes(m)
  );
  if (importantNeglected.length > 0) {
    adviceParts.push(`Не тренируются: ${importantNeglected.join(', ')}.`);
  }

  return {
    pushPullRatio,
    upperLowerRatio,
    neglectedMuscles,
    overtrainedMuscles,
    advice: adviceParts.join(' '),
  };
}

function buildMuscleBalanceContext(balance: MuscleBalanceResult): string {
  if (!balance.advice) return '';

  return `\n## ⚖️ МЫШЕЧНЫЙ БАЛАНС (анализ за последние 2 недели)
Push/Pull: ${balance.pushPullRatio.toFixed(1)} (норма: ~1.0)
Верх/Низ: ${balance.upperLowerRatio.toFixed(1)} (норма: ~1.0-1.5)
${balance.advice}
→ Если пользователь спрашивает программу или упражнения — учти этот дисбаланс.`;
}

// ─── Block 25: Deload Week Auto-Detection ──────────────────────────────────

interface DeloadRecommendation {
  shouldDeload: boolean;
  reason: string;
  weeksSinceDeload: number;
  suggestedAction: string;
}

/**
 * Analyze training history to determine if the user needs a deload week.
 * Factors:
 * 1. Weeks of continuous training without deload (>4-6 weeks = likely needs one)
 * 2. Plateaus across multiple exercises
 * 3. Volume/intensity trends (consecutive increases = accumulated fatigue)
 * 4. Recovery score trend
 */
function detectDeloadNeed(
  recentWorkouts: Array<{ name: string; completedAt: Date | null; totalVolume: number | null }>,
  overloadData: OverloadStatus[],
  recoveryScore: number,
): DeloadRecommendation {
  const now = Date.now();
  const MS_PER_WEEK = 7 * 24 * 60 * 60 * 1000;

  // Count consecutive weeks with training
  let consecutiveWeeks = 0;
  for (let w = 0; w < 8; w++) {
    const weekStart = now - (w + 1) * MS_PER_WEEK;
    const weekEnd = now - w * MS_PER_WEEK;
    const workoutsInWeek = recentWorkouts.filter((wo) => {
      const t = wo.completedAt ? wo.completedAt.getTime() : 0;
      return t >= weekStart && t < weekEnd;
    });
    if (workoutsInWeek.length >= 2) {
      consecutiveWeeks++;
    } else {
      break; // found a rest/deload week
    }
  }

  // Check for volume trend (are last 3 weeks showing increasing or flat-high volume?)
  const weeklyVolumes: number[] = [];
  for (let w = 0; w < 4; w++) {
    const weekStart = now - (w + 1) * MS_PER_WEEK;
    const weekEnd = now - w * MS_PER_WEEK;
    const vol = recentWorkouts
      .filter((wo) => {
        const t = wo.completedAt ? wo.completedAt.getTime() : 0;
        return t >= weekStart && t < weekEnd;
      })
      .reduce((sum, wo) => sum + (wo.totalVolume || 0), 0);
    weeklyVolumes.push(vol);
  }

  // Count plateaus
  const plateauCount = overloadData.filter((o) => o.status === 'plateau').length;
  const regressionCount = overloadData.filter((o) => o.status === 'regressing').length;

  // Decision logic
  let shouldDeload = false;
  let reason = '';
  let suggestedAction = '';

  if (consecutiveWeeks >= 6) {
    shouldDeload = true;
    reason = `${consecutiveWeeks} недель подряд без разгрузки — накопленная усталость гарантирована`;
    suggestedAction = 'Рекомендуй deload неделю: сохранить упражнения, снизить вес на 40-50%, объём на 30-40%';
  } else if (consecutiveWeeks >= 4 && (plateauCount >= 2 || recoveryScore < 50)) {
    shouldDeload = true;
    reason = `${consecutiveWeeks} недель без отдыха + ${plateauCount >= 2 ? `плато в ${plateauCount} упражнениях` : `низкий recovery score (${recoveryScore})`}`;
    suggestedAction = 'Предложи облегчённую неделю: снизить рабочие веса на 30%, убрать изоляцию, оставить базовые';
  } else if (regressionCount >= 3) {
    shouldDeload = true;
    reason = `Регрессия в ${regressionCount} упражнениях — явный признак перетренированности`;
    suggestedAction = 'СРОЧНО рекомендуй полный отдых 3-5 дней или очень лёгкую восстановительную тренировку';
  } else if (consecutiveWeeks >= 4 && recoveryScore < 60 && weeklyVolumes[0] > weeklyVolumes[1]) {
    shouldDeload = true;
    reason = `Усталость при растущем объёме — классический сигнал для deload`;
    suggestedAction = 'Предложи следующую неделю сделать разгрузочной: те же упражнения, 60% от рабочих весов';
  }

  return {
    shouldDeload,
    reason,
    weeksSinceDeload: consecutiveWeeks,
    suggestedAction,
  };
}

function buildDeloadContext(deload: DeloadRecommendation): string {
  if (!deload.shouldDeload) return '';

  return `\n## ⚠️ DELOAD РЕКОМЕНДАЦИЯ (ВАЖНО)
Причина: ${deload.reason}
Тренировочных недель подряд: ${deload.weeksSinceDeload}
→ ${deload.suggestedAction}
→ Объясни пользователю ЗАЧЕМ нужен deload (суперкомпенсация, адаптация ЦНС, профилактика травм).`;
}

// ─── Block 29: Volume Periodization Advisor ─────────────────────────────────

type MesocyclePhase = 'accumulation' | 'intensification' | 'deload' | 'peaking' | 'unknown';

interface PeriodizationAdvice {
  currentPhase: MesocyclePhase;
  weekInPhase: number;
  suggestion: string;
}

/**
 * Analyze weekly volume trends to determine current training phase
 * and suggest next phase transitions.
 */
function getPeriodizationAdvice(
  recentWorkouts: Array<{ completedAt: Date | null; totalVolume: number | null }>,
): PeriodizationAdvice {
  const now = Date.now();
  const MS_PER_WEEK = 7 * 24 * 60 * 60 * 1000;

  // Calculate weekly volumes for last 6 weeks
  const weeklyVolumes: number[] = [];
  const weeklyWorkoutCounts: number[] = [];
  for (let w = 0; w < 6; w++) {
    const weekStart = now - (w + 1) * MS_PER_WEEK;
    const weekEnd = now - w * MS_PER_WEEK;
    const weekWorkouts = recentWorkouts.filter((wo) => {
      const t = wo.completedAt ? wo.completedAt.getTime() : 0;
      return t >= weekStart && t < weekEnd;
    });
    weeklyVolumes.push(weekWorkouts.reduce((sum, wo) => sum + (wo.totalVolume || 0), 0));
    weeklyWorkoutCounts.push(weekWorkouts.length);
  }

  // Reverse so [0] = oldest, [5] = most recent
  weeklyVolumes.reverse();
  weeklyWorkoutCounts.reverse();

  if (weeklyVolumes.filter((v) => v > 0).length < 3) {
    return { currentPhase: 'unknown', weekInPhase: 0, suggestion: '' };
  }

  // Detect volume trend
  const recent3 = weeklyVolumes.slice(-3);
  const isIncreasing = recent3[2] > recent3[1] && recent3[1] > recent3[0];
  const isDecreasing = recent3[2] < recent3[1] && recent3[1] < recent3[0];
  const isFlat = Math.abs(recent3[2] - recent3[0]) / Math.max(recent3[0], 1) < 0.1;

  // Determine average intensity (volume per workout)
  const recentAvgVolPerWorkout = weeklyWorkoutCounts[5] > 0
    ? weeklyVolumes[5] / weeklyWorkoutCounts[5]
    : 0;
  const olderAvgVolPerWorkout = weeklyWorkoutCounts[2] > 0
    ? weeklyVolumes[2] / weeklyWorkoutCounts[2]
    : 0;

  let currentPhase: MesocyclePhase = 'unknown';
  let weekInPhase = 0;
  let suggestion = '';

  if (isIncreasing) {
    currentPhase = 'accumulation';
    // Count consecutive increasing weeks
    for (let i = weeklyVolumes.length - 1; i > 0; i--) {
      if (weeklyVolumes[i] >= weeklyVolumes[i - 1]) weekInPhase++;
      else break;
    }

    if (weekInPhase >= 4) {
      suggestion = `Уже ${weekInPhase} недель нарастающего объёма. Рекомендуется перейти к фазе интенсификации: снизить объём на 20%, повысить рабочие веса на 5-10%.`;
    } else if (weekInPhase >= 3) {
      suggestion = `Фаза накопления (${weekInPhase} недель). Ещё 1-2 недели роста объёма, затем переход к интенсификации.`;
    }
  } else if (isDecreasing && recentAvgVolPerWorkout > olderAvgVolPerWorkout * 0.95) {
    // Volume down but intensity per workout up = intensification
    currentPhase = 'intensification';
    weekInPhase = 2;
    suggestion = `Фаза интенсификации: объём снижается, но интенсивность на тренировку растёт. Это хорошо — через 1-2 недели можно сделать deload.`;
  } else if (isDecreasing && recentAvgVolPerWorkout <= olderAvgVolPerWorkout * 0.7) {
    currentPhase = 'deload';
    weekInPhase = 1;
    suggestion = `Похоже на разгрузочную неделю. После неё — начинай новый мезоцикл с повышенными весами.`;
  } else if (isFlat) {
    currentPhase = 'accumulation';
    weekInPhase = 3;
    suggestion = `Объём стабильный — стагнация. Для прогресса нужно либо повышать объём на 5-10% в неделю, либо увеличить рабочие веса.`;
  }

  return { currentPhase, weekInPhase, suggestion };
}

function buildPeriodizationContext(advice: PeriodizationAdvice): string {
  if (!advice.suggestion || advice.currentPhase === 'unknown') return '';

  const phaseLabels: Record<MesocyclePhase, string> = {
    accumulation: 'Накопление (объём↑)',
    intensification: 'Интенсификация (вес↑, объём↓)',
    deload: 'Разгрузка',
    peaking: 'Пиковая',
    unknown: '',
  };

  return `\n## 📈 ПЕРИОДИЗАЦИЯ
Текущая фаза: ${phaseLabels[advice.currentPhase]} (неделя ${advice.weekInPhase})
${advice.suggestion}
→ Учитывай фазу при рекомендациях по программе и нагрузке.`;
}

// ─── Block 30: Smart Greeting — context-aware first message ─────────────────

interface GreetingContext {
  timeOfDay: string; // утро/день/вечер/ночь
  userName: string;
  daysSinceLastWorkout: number | null;
  lastWorkoutName: string | null;
  streak: number;
  scheduledToday: string | null;
  todayMealsCount: number;
  bodyWeightTrend: string | null; // 'up' | 'down' | 'stable' | null
  newPRs: string[];
  recoveryScore: number;
  deloadNeeded: boolean;
}

function buildSmartGreetingDirective(ctx: GreetingContext): string {
  const lines: string[] = [];

  // Time-appropriate greeting
  const greetingMap: Record<string, string> = {
    'утро': `Доброе утро, ${ctx.userName}!`,
    'день': `Добрый день, ${ctx.userName}!`,
    'вечер': `Добрый вечер, ${ctx.userName}!`,
    'ночь': `${ctx.userName}, не поздновато для тренировки? 😄`,
  };
  lines.push(`Начни с приветствия: "${greetingMap[ctx.timeOfDay]}"`);

  // Last workout context
  if (ctx.daysSinceLastWorkout !== null) {
    if (ctx.daysSinceLastWorkout === 0) {
      lines.push(`Пользователь уже тренировался сегодня (${ctx.lastWorkoutName}). Похвали и спроси как самочувствие.`);
    } else if (ctx.daysSinceLastWorkout === 1) {
      lines.push(`Вчера была тренировка "${ctx.lastWorkoutName}". Спроси про восстановление или предложи следующую.`);
    } else if (ctx.daysSinceLastWorkout <= 3) {
      lines.push(`Последняя тренировка ${ctx.daysSinceLastWorkout} дня назад ("${ctx.lastWorkoutName}"). Мягко предложи тренировку.`);
    } else if (ctx.daysSinceLastWorkout <= 7) {
      lines.push(`Перерыв ${ctx.daysSinceLastWorkout} дней. Мотивируй вернуться, но без давления.`);
    } else {
      lines.push(`Долгий перерыв (${ctx.daysSinceLastWorkout} дней). Предложи лёгкую тренировку для возвращения в ритм.`);
    }
  }

  // Streak
  if (ctx.streak >= 7) {
    lines.push(`🔥 Серия ${ctx.streak} дней! Обязательно отметь это достижение.`);
  } else if (ctx.streak >= 3) {
    lines.push(`Серия ${ctx.streak} дней — хорошо, поддержи мотивацию.`);
  }

  // Scheduled workout today
  if (ctx.scheduledToday) {
    lines.push(`Сегодня запланирована тренировка "${ctx.scheduledToday}". Напомни и предложи начать.`);
  }

  // Nutrition check
  if (ctx.todayMealsCount === 0) {
    const hour = new Date().getHours();
    if (hour >= 10) {
      lines.push(`Пользователь ещё не записал ни одного приёма пищи сегодня. Если уместно — напомни.`);
    }
  }

  // Body weight trend
  if (ctx.bodyWeightTrend === 'down') {
    lines.push(`Вес снижается — если цель похудение, похвали прогресс.`);
  } else if (ctx.bodyWeightTrend === 'up') {
    lines.push(`Вес растёт — если цель набор массы, отметь прогресс. Если похудение — деликатно предложи корректировку.`);
  }

  // New PRs
  if (ctx.newPRs.length > 0) {
    lines.push(`🎉 Недавние рекорды: ${ctx.newPRs.join(', ')}. Обязательно поздравь!`);
  }

  // Recovery warning
  if (ctx.recoveryScore < 50) {
    lines.push(`⚠️ Восстановление ${ctx.recoveryScore}% — предложи лёгкую тренировку или день отдыха.`);
  }

  // Deload
  if (ctx.deloadNeeded) {
    lines.push(`Нужна разгрузочная неделя — мягко предложи deload.`);
  }

  lines.push(`Будь кратким (3-5 предложений), дружелюбным и проактивным. НЕ перечисляй все пункты подряд — выбери 2-3 самых важных.`);

  return `\n\n## 🤝 ИНСТРУКЦИЯ ДЛЯ ПРИВЕТСТВИЯ\n${lines.join('\n')}`;
}

// ─── Block 31: Workout Difficulty Auto-Adjustment ───────────────────────────
// Analyzes last completed workout RPE and completion rates to suggest weight/rep changes

interface DifficultyAdjustment {
  exerciseName: string;
  currentWeight: number;
  suggestedWeight: number;
  currentReps: number;
  suggestedReps: number;
  reason: string;
}

function analyzeDifficultyAdjustments(
  lastWorkoutExercises: Array<{
    exercise: { name: string };
    sets: Array<{ weight: number | null; reps: number | null; rpe: number | null; completed: boolean }>;
  }>
): DifficultyAdjustment[] {
  const adjustments: DifficultyAdjustment[] = [];

  for (const we of lastWorkoutExercises) {
    const completedSets = we.sets.filter((s) => s.completed);
    if (completedSets.length === 0) continue;

    const avgWeight = completedSets.reduce((s, set) => s + (set.weight || 0), 0) / completedSets.length;
    const avgReps = completedSets.reduce((s, set) => s + (set.reps || 0), 0) / completedSets.length;
    const avgRpe = completedSets.filter((s) => s.rpe).reduce((s, set) => s + (set.rpe || 0), 0) / (completedSets.filter((s) => s.rpe).length || 1);
    const completionRate = completedSets.length / we.sets.length;

    if (avgWeight === 0) continue;

    // Too easy: all sets completed, low RPE
    if (completionRate === 1 && avgRpe > 0 && avgRpe < 7) {
      const increase = avgRpe < 5 ? 0.1 : 0.05; // +10% or +5%
      adjustments.push({
        exerciseName: we.exercise.name,
        currentWeight: Math.round(avgWeight),
        suggestedWeight: Math.round(avgWeight * (1 + increase) / 2.5) * 2.5, // round to 2.5kg
        currentReps: Math.round(avgReps),
        suggestedReps: Math.round(avgReps),
        reason: `RPE ${avgRpe.toFixed(0)} — слишком легко. Увеличь вес на ${Math.round(increase * 100)}%.`,
      });
    }

    // Too hard: low completion, high RPE
    if (completionRate < 0.7 || (avgRpe >= 9.5)) {
      const decrease = completionRate < 0.5 ? 0.15 : 0.1;
      adjustments.push({
        exerciseName: we.exercise.name,
        currentWeight: Math.round(avgWeight),
        suggestedWeight: Math.round(avgWeight * (1 - decrease) / 2.5) * 2.5,
        currentReps: Math.round(avgReps),
        suggestedReps: Math.round(avgReps),
        reason: completionRate < 0.7
          ? `Выполнено только ${Math.round(completionRate * 100)}% подходов — снизь вес на ${Math.round(decrease * 100)}%.`
          : `RPE ${avgRpe.toFixed(0)} — на пределе. Снизь вес на ${Math.round(decrease * 100)}% для безопасного прогресса.`,
      });
    }

    // Rep target not met consistently (completed but fewer reps than planned)
    if (completionRate >= 0.8 && avgRpe >= 8 && avgRpe < 9.5) {
      // This is the "productive" zone — just acknowledge it
      // No adjustment needed
    }
  }

  return adjustments;
}

function buildDifficultyContext(adjustments: DifficultyAdjustment[]): string {
  if (adjustments.length === 0) return '';

  const lines = adjustments.slice(0, 4).map((a) =>
    `- **${a.exerciseName}**: ${a.currentWeight}кг → ${a.suggestedWeight}кг (${a.reason})`
  );

  return `\n\n## ⚖️ РЕКОМЕНДАЦИИ ПО НАГРУЗКЕ (на основе последней тренировки)
${lines.join('\n')}
→ Если пользователь спрашивает про веса или программу — предложи эти корректировки.`;
}

// ─── Block 32: Contextual Exercise Alternatives ─────────────────────────────
// Suggest exercise swaps based on injuries, equipment, and muscle targeting

interface ExerciseAlternative {
  original: string;
  alternatives: string[];
  reason: string;
}

const EXERCISE_ALTERNATIVES: Record<string, { alternatives: string[]; muscles: string[] }> = {
  'Жим штанги лёжа': { alternatives: ['Жим гантелей лёжа', 'Жим в тренажёре Смита', 'Отжимания от пола'], muscles: ['chest', 'triceps'] },
  'Приседания со штангой': { alternatives: ['Жим ногами', 'Гоблет-приседания', 'Болгарские сплит-приседания'], muscles: ['quadriceps', 'glutes'] },
  'Становая тяга': { alternatives: ['Румынская тяга', 'Тяга трэп-грифа', 'Гиперэкстензия'], muscles: ['back', 'hamstrings'] },
  'Жим штанги стоя': { alternatives: ['Жим гантелей сидя', 'Жим Арнольда', 'Жим в тренажёре Смита сидя'], muscles: ['shoulders'] },
  'Тяга штанги в наклоне': { alternatives: ['Тяга гантелей в наклоне', 'Тяга нижнего блока', 'Тяга Т-грифа'], muscles: ['back', 'biceps'] },
  'Подтягивания': { alternatives: ['Тяга верхнего блока', 'Подтягивания в гравитроне', 'Тяга гантели одной рукой'], muscles: ['back', 'biceps'] },
  'Французский жим': { alternatives: ['Разгибания рук на блоке', 'Отжимания на брусьях', 'Жим узким хватом'], muscles: ['triceps'] },
  'Подъём штанги на бицепс': { alternatives: ['Подъём гантелей на бицепс', 'Молоток', 'Сгибания на блоке'], muscles: ['biceps'] },
  'Разведение гантелей': { alternatives: ['Сведения в тренажёре Пек-Дек', 'Кроссовер', 'Разведения на наклонной скамье'], muscles: ['chest'] },
  'Выпады': { alternatives: ['Болгарские сплит-приседания', 'Шаги на платформу', 'Жим одной ногой'], muscles: ['quadriceps', 'glutes'] },
};

const INJURY_EXERCISE_BLACKLIST: Record<string, string[]> = {
  'shoulder': ['Жим штанги стоя', 'Жим штанги лёжа', 'Разведение гантелей', 'Французский жим'],
  'knee': ['Приседания со штангой', 'Выпады', 'Жим ногами'],
  'lower_back': ['Становая тяга', 'Тяга штанги в наклоне', 'Приседания со штангой'],
  'wrist': ['Подъём штанги на бицепс', 'Жим штанги лёжа', 'Французский жим'],
  'elbow': ['Французский жим', 'Подъём штанги на бицепс', 'Жим узким хватом'],
};

function getExerciseAlternatives(
  programExercises: string[],
  injuryZones: string[],
): ExerciseAlternative[] {
  const result: ExerciseAlternative[] = [];

  // Find exercises that conflict with injuries
  for (const zone of injuryZones) {
    const blacklisted = INJURY_EXERCISE_BLACKLIST[zone] || [];
    for (const exercise of programExercises) {
      if (blacklisted.includes(exercise)) {
        const alts = EXERCISE_ALTERNATIVES[exercise];
        if (alts) {
          // Filter out alternatives that are also blacklisted
          const safeAlts = alts.alternatives.filter((a) =>
            !blacklisted.includes(a) && !injuryZones.some((z) => (INJURY_EXERCISE_BLACKLIST[z] || []).includes(a))
          );
          if (safeAlts.length > 0) {
            result.push({
              original: exercise,
              alternatives: safeAlts,
              reason: `⚠️ Может усугубить проблему с ${zone === 'shoulder' ? 'плечом' : zone === 'knee' ? 'коленом' : zone === 'lower_back' ? 'поясницей' : zone === 'wrist' ? 'запястьем' : zone === 'elbow' ? 'локтем' : zone}`,
            });
          }
        }
      }
    }
  }

  return result;
}

function buildExerciseAlternativesContext(alternatives: ExerciseAlternative[]): string {
  if (alternatives.length === 0) return '';

  const lines = alternatives.slice(0, 3).map((a) =>
    `- **${a.original}** → ${a.alternatives.join(' / ')} (${a.reason})`
  );

  return `\n\n## 🔄 РЕКОМЕНДУЕМЫЕ ЗАМЕНЫ УПРАЖНЕНИЙ
${lines.join('\n')}
→ Предлагай замены при обсуждении тренировок. Всегда объясняй почему.`;
}

// ─── Block 33: Weekly Training Summary ──────────────────────────────────────
// Auto-generated weekly digest for AI context

interface WeeklySummary {
  totalWorkouts: number;
  totalVolume: number;
  totalDuration: number;
  musclesWorked: string[];
  avgRpe: number | null;
  completionRate: number; // % of planned workouts done
  volumeChange: number; // % change from prev week
  highlights: string[];
}

function buildWeeklySummary(
  thisWeekWorkouts: Array<{
    name: string;
    completedAt: Date | null;
    totalVolume: number | null;
    durationMinutes: number | null;
    exercises: Array<{
      exercise: { name: string; primaryMuscles: string[] };
      sets: Array<{ rpe: number | null; completed: boolean }>;
    }>;
  }>,
  prevWeekVolume: number,
  plannedDays: number,
): WeeklySummary {
  const completed = thisWeekWorkouts.filter((w) => w.completedAt);
  const totalVolume = completed.reduce((s, w) => s + (w.totalVolume || 0), 0);
  const totalDuration = completed.reduce((s, w) => s + (w.durationMinutes || 0), 0);

  // Muscles worked
  const muscleSet = new Set<string>();
  for (const w of completed) {
    for (const ex of w.exercises) {
      ex.exercise.primaryMuscles.forEach((m) => muscleSet.add(m));
    }
  }

  // Average RPE
  let rpeSum = 0; let rpeCount = 0;
  for (const w of completed) {
    for (const ex of w.exercises) {
      for (const s of ex.sets) {
        if (s.rpe) { rpeSum += s.rpe; rpeCount++; }
      }
    }
  }

  const volumeChange = prevWeekVolume > 0
    ? Math.round(((totalVolume - prevWeekVolume) / prevWeekVolume) * 100)
    : 0;

  const highlights: string[] = [];
  if (completed.length >= plannedDays && plannedDays > 0) {
    highlights.push(`✅ План выполнен: ${completed.length}/${plannedDays} тренировок`);
  } else if (completed.length > 0 && plannedDays > 0) {
    highlights.push(`⏳ ${completed.length}/${plannedDays} тренировок на этой неделе`);
  }
  if (volumeChange > 10) highlights.push(`📈 Объём +${volumeChange}% к прошлой неделе`);
  if (volumeChange < -15) highlights.push(`📉 Объём ${volumeChange}% к прошлой неделе`);
  if (rpeCount > 0 && rpeSum / rpeCount >= 9) highlights.push(`⚠️ Средний RPE ${(rpeSum / rpeCount).toFixed(1)} — возможна перегрузка`);

  return {
    totalWorkouts: completed.length,
    totalVolume: Math.round(totalVolume),
    totalDuration: Math.round(totalDuration),
    musclesWorked: [...muscleSet],
    avgRpe: rpeCount > 0 ? Math.round((rpeSum / rpeCount) * 10) / 10 : null,
    completionRate: plannedDays > 0 ? Math.round((completed.length / plannedDays) * 100) : 0,
    volumeChange,
    highlights,
  };
}

function buildWeeklySummaryContext(summary: WeeklySummary): string {
  if (summary.totalWorkouts === 0) return '';

  const lines = [
    `Тренировок: ${summary.totalWorkouts}, объём: ${summary.totalVolume} кг, длительность: ${summary.totalDuration} мин`,
    `Мышцы: ${summary.musclesWorked.join(', ')}`,
    summary.avgRpe ? `Средний RPE: ${summary.avgRpe}` : null,
    summary.volumeChange !== 0 ? `Изменение объёма: ${summary.volumeChange > 0 ? '+' : ''}${summary.volumeChange}%` : null,
    ...summary.highlights,
  ].filter(Boolean);

  return `\n\n## 📊 ИТОГИ НЕДЕЛИ
${lines.join('\n')}
→ Используй при ответах о прогрессе, плане и мотивации.`;
}

// ─── Block 34: Goal Progress Tracker ────────────────────────────────────────
// Estimates progress toward user's goal and time to achieve it

interface GoalProgress {
  goal: string;
  progressPercent: number;
  estimatedWeeksLeft: number | null;
  insight: string;
  onTrack: boolean;
}

function estimateGoalProgress(
  user: { weightKg?: number | null; goal?: string | null; fitnessLevel?: string | null },
  bodyWeightHistory: Array<{ weightKg: number; date: Date }>,
  totalWorkoutsLast30Days: number,
  weeklyAvgVolume: number,
): GoalProgress | null {
  if (!user.goal) return null;

  const goal = user.goal;
  const currentWeight = user.weightKg || bodyWeightHistory[0]?.weightKg;

  if (goal === 'WEIGHT_LOSS') {
    if (!currentWeight || bodyWeightHistory.length < 3) {
      return { goal: 'Похудение', progressPercent: 0, estimatedWeeksLeft: null, insight: 'Недостаточно данных о весе. Записывай вес регулярно для отслеживания прогресса.', onTrack: false };
    }
    // Calculate weekly weight loss rate
    const oldest = bodyWeightHistory[bodyWeightHistory.length - 1];
    const weeksBetween = Math.max(1, (Date.now() - new Date(oldest.date).getTime()) / (7 * 24 * 60 * 60 * 1000));
    const totalLoss = oldest.weightKg - currentWeight;
    const weeklyRate = totalLoss / weeksBetween;

    // Estimate target: ~10-15% body fat reduction for general weight loss
    const targetWeight = currentWeight * 0.9; // ~10% loss as rough target
    const remainingLoss = currentWeight - targetWeight;

    if (weeklyRate > 0) {
      const weeksLeft = Math.round(remainingLoss / weeklyRate);
      const onTrack = weeklyRate >= 0.3 && weeklyRate <= 1.0;
      return {
        goal: 'Похудение',
        progressPercent: Math.min(100, Math.round((totalLoss / (totalLoss + remainingLoss)) * 100)),
        estimatedWeeksLeft: weeksLeft > 0 ? weeksLeft : null,
        insight: onTrack
          ? `Темп потери: ${weeklyRate.toFixed(1)} кг/нед — оптимально (0.3-1.0 кг/нед).`
          : weeklyRate > 1.0
            ? `Темп потери: ${weeklyRate.toFixed(1)} кг/нед — слишком быстро! Риск потери мышц. Добавь 200-300 ккал.`
            : `Темп потери: ${weeklyRate.toFixed(1)} кг/нед — медленно. Рассмотри снижение калорий на 200 ккал или добавление кардио.`,
        onTrack,
      };
    }

    return { goal: 'Похудение', progressPercent: 0, estimatedWeeksLeft: null, insight: `Вес не снижается или растёт. Проверь калорийность и увеличь активность.`, onTrack: false };
  }

  if (goal === 'MUSCLE_GAIN') {
    if (!currentWeight || bodyWeightHistory.length < 3) {
      return { goal: 'Набор массы', progressPercent: 0, estimatedWeeksLeft: null, insight: 'Записывай вес регулярно для отслеживания набора.', onTrack: false };
    }
    const oldest = bodyWeightHistory[bodyWeightHistory.length - 1];
    const weeksBetween = Math.max(1, (Date.now() - new Date(oldest.date).getTime()) / (7 * 24 * 60 * 60 * 1000));
    const totalGain = currentWeight - oldest.weightKg;
    const weeklyRate = totalGain / weeksBetween;

    const onTrack = weeklyRate >= 0.2 && weeklyRate <= 0.5;
    return {
      goal: 'Набор массы',
      progressPercent: Math.min(100, Math.round(totalWorkoutsLast30Days / 16 * 100)), // ~4 workouts/week target
      estimatedWeeksLeft: null,
      insight: onTrack
        ? `Набор: ${weeklyRate.toFixed(1)} кг/нед — идеально для чистого набора.`
        : weeklyRate > 0.5
          ? `Набор: ${weeklyRate.toFixed(1)} кг/нед — слишком быстро, часть уйдёт в жир. Снизь профицит на 200 ккал.`
          : weeklyRate < 0.1
            ? `Набор: ${weeklyRate.toFixed(1)} кг/нед — медленно. Увеличь калорийность на 300 ккал.`
            : `Набор: ${weeklyRate.toFixed(1)} кг/нед.`,
      onTrack,
    };
  }

  if (goal === 'STRENGTH') {
    const onTrack = totalWorkoutsLast30Days >= 12 && weeklyAvgVolume > 0;
    return {
      goal: 'Сила',
      progressPercent: Math.min(100, Math.round(totalWorkoutsLast30Days / 16 * 100)),
      estimatedWeeksLeft: null,
      insight: onTrack
        ? `${totalWorkoutsLast30Days} тренировок за 30 дней — отличная регулярность для силового прогресса.`
        : totalWorkoutsLast30Days < 8
          ? `Только ${totalWorkoutsLast30Days} тренировок за 30 дней — для силы нужна регулярность (3-4 раза/нед).`
          : `${totalWorkoutsLast30Days} тренировок за 30 дней — хорошо, но стремись к 4/нед.`,
      onTrack,
    };
  }

  return null;
}

function buildGoalProgressContext(progress: GoalProgress | null): string {
  if (!progress) return '';

  return `\n\n## 🎯 ПРОГРЕСС К ЦЕЛИ: ${progress.goal.toUpperCase()}
Прогресс: ${progress.progressPercent}%${progress.estimatedWeeksLeft ? ` (~${progress.estimatedWeeksLeft} нед до цели)` : ''}
${progress.insight}
${progress.onTrack ? '✅ На верном пути' : '⚠️ Требуется корректировка'}
→ Используй при мотивации и корректировке программы/питания.`;
}

// ─── Block 35: Smart Rest Timer Suggestion ──────────────────────────────────
// Suggest rest times based on exercise type, RPE, goals, and set type

function getSmartRestSuggestion(
  exerciseCategory: string, // strength, cardio, flexibility
  exerciseType: string, // barbell, dumbbell, machine, bodyweight
  setType: string, // normal, warmup, dropset, superset
  lastRpe: number | null,
  userGoal: string | null,
): { restSeconds: number; reason: string } {
  // Base rest by exercise type
  let baseRest = 90;

  // Compound barbell exercises need more rest
  if (exerciseType === 'barbell') baseRest = 120;
  else if (exerciseType === 'machine') baseRest = 60;
  else if (exerciseType === 'bodyweight') baseRest = 60;
  else if (exerciseType === 'cable') baseRest = 60;

  // Adjust by set type
  if (setType === 'warmup') return { restSeconds: 60, reason: 'Разминочный подход — 60 сек достаточно.' };
  if (setType === 'dropset') return { restSeconds: 15, reason: 'Дроп-сет — минимальный отдых (10-15 сек) для максимального пампинга.' };
  if (setType === 'superset') return { restSeconds: 30, reason: 'Суперсет — 30 сек между упражнениями, 90 сек между кругами.' };

  // Adjust by goal
  if (userGoal === 'STRENGTH') {
    baseRest = Math.max(baseRest, 180); // 3+ min for strength
  } else if (userGoal === 'MUSCLE_GAIN') {
    baseRest = Math.min(baseRest, 90); // 60-90s hypertrophy
  } else if (userGoal === 'WEIGHT_LOSS') {
    baseRest = Math.min(baseRest, 60); // shorter rest for caloric burn
  } else if (userGoal === 'ENDURANCE') {
    baseRest = Math.min(baseRest, 45);
  }

  // Adjust by RPE (fatigue)
  if (lastRpe !== null) {
    if (lastRpe >= 9) baseRest += 60; // very hard — need extra recovery
    else if (lastRpe >= 8) baseRest += 30;
  }

  let reason = '';
  if (userGoal === 'STRENGTH') reason = `Силовая цель — длинный отдых (${baseRest} сек) для полного восстановления АТФ.`;
  else if (userGoal === 'MUSCLE_GAIN') reason = `Гипертрофия — ${baseRest} сек для оптимального метаболического стресса.`;
  else if (userGoal === 'WEIGHT_LOSS') reason = `Жиросжигание — ${baseRest} сек для поддержания ЧСС.`;
  else reason = `Рекомендуемый отдых: ${baseRest} сек.`;

  return { restSeconds: baseRest, reason };
}

function buildRestTimerContext(
  userGoal: string | null,
  exerciseTypes: string[], // types from current program
): string {
  if (!userGoal || exerciseTypes.length === 0) return '';

  // Generate general recommendations
  const recommendations: string[] = [];

  const barbellRest = getSmartRestSuggestion('strength', 'barbell', 'normal', null, userGoal);
  const machineRest = getSmartRestSuggestion('strength', 'machine', 'normal', null, userGoal);

  if (barbellRest.restSeconds !== machineRest.restSeconds) {
    recommendations.push(`Базовые (штанга): ${barbellRest.restSeconds} сек — ${barbellRest.reason}`);
    recommendations.push(`Изоляция (тренажёры): ${machineRest.restSeconds} сек — ${machineRest.reason}`);
  } else {
    recommendations.push(`Стандартный отдых: ${barbellRest.restSeconds} сек — ${barbellRest.reason}`);
  }

  if (userGoal === 'STRENGTH') {
    recommendations.push('При RPE 9+ — добавь ещё 60 сек для восстановления.');
  }

  return `\n\n## ⏱ РЕКОМЕНДАЦИИ ПО ОТДЫХУ
${recommendations.join('\n')}
→ Предлагай персонализированное время отдыха при обсуждении тренировок.`;
}

// ─── Block 36: Fatigue Index ────────────────────────────────────────────────
// Cumulative weekly load scoring using simplified TRIMP-like model

interface FatigueData {
  acuteLoad: number;    // last 7 days
  chronicLoad: number;  // last 28 days average per week
  ratio: number;        // acute:chronic ratio (ACWR)
  status: 'fresh' | 'optimal' | 'overreaching' | 'dangerous';
  message: string;
}

function calculateFatigueIndex(
  workouts: Array<{ completedAt: Date | null; totalVolume: number | null; durationMinutes: number | null }>,
): FatigueData {
  const now = Date.now();
  const MS_PER_DAY = 24 * 60 * 60 * 1000;

  // Calculate load as volume × duration proxy
  const getLoad = (wo: typeof workouts[number]) => {
    const vol = wo.totalVolume || 0;
    const dur = wo.durationMinutes || 45;
    return vol * (dur / 60); // volume-hours
  };

  const last7Days = workouts.filter((w) => w.completedAt && (now - new Date(w.completedAt).getTime()) < 7 * MS_PER_DAY);
  const last28Days = workouts.filter((w) => w.completedAt && (now - new Date(w.completedAt).getTime()) < 28 * MS_PER_DAY);

  const acuteLoad = last7Days.reduce((s, w) => s + getLoad(w), 0);
  const chronicLoad = last28Days.length > 0
    ? last28Days.reduce((s, w) => s + getLoad(w), 0) / 4 // average weekly load over 4 weeks
    : acuteLoad;

  const ratio = chronicLoad > 0 ? Math.round((acuteLoad / chronicLoad) * 100) / 100 : 1;

  let status: FatigueData['status'];
  let message: string;

  if (ratio < 0.8) {
    status = 'fresh';
    message = `Нагрузка ниже обычной (ACWR: ${ratio}). Можно увеличить объём или интенсивность.`;
  } else if (ratio <= 1.3) {
    status = 'optimal';
    message = `Нагрузка в оптимальной зоне (ACWR: ${ratio}). Продолжай в том же духе!`;
  } else if (ratio <= 1.5) {
    status = 'overreaching';
    message = `⚠️ Нагрузка повышена (ACWR: ${ratio}). Возможно функциональное перенапряжение. Следи за восстановлением.`;
  } else {
    status = 'dangerous';
    message = `🚨 Нагрузка критически высокая (ACWR: ${ratio}). Высокий риск травмы! Рекомендуется снизить объём на 30-40%.`;
  }

  return { acuteLoad: Math.round(acuteLoad), chronicLoad: Math.round(chronicLoad), ratio, status, message };
}

function buildFatigueContext(fatigue: FatigueData): string {
  if (fatigue.acuteLoad === 0 && fatigue.chronicLoad === 0) return '';

  return `\n\n## 🔋 ИНДЕКС УСТАЛОСТИ (ACWR)
Острая нагрузка (7д): ${fatigue.acuteLoad} | Хроническая (28д/нед): ${fatigue.chronicLoad}
Соотношение: ${fatigue.ratio} — ${fatigue.message}
→ Учитывай при рекомендациях по объёму и интенсивности.`;
}

// ─── Block 37: Training Frequency Optimizer ─────────────────────────────────
// Analyze recovery patterns to suggest optimal training frequency

function analyzeTrainingFrequency(
  workouts: Array<{ completedAt: Date | null; name: string }>,
  recoveryScore: number,
  userGoal: string | null,
): string {
  if (workouts.length < 4) return '';

  const completed = workouts.filter((w) => w.completedAt).sort(
    (a, b) => new Date(a.completedAt!).getTime() - new Date(b.completedAt!).getTime()
  );

  if (completed.length < 3) return '';

  // Calculate average gap between workouts (in days)
  const gaps: number[] = [];
  for (let i = 1; i < completed.length; i++) {
    const gap = (new Date(completed[i].completedAt!).getTime() - new Date(completed[i - 1].completedAt!).getTime()) / (24 * 60 * 60 * 1000);
    gaps.push(gap);
  }

  const avgGap = gaps.reduce((s, g) => s + g, 0) / gaps.length;
  const currentFrequency = Math.round(7 / avgGap * 10) / 10; // workouts per week

  let suggestedFrequency: number;
  let suggestion: string;

  if (userGoal === 'STRENGTH') {
    suggestedFrequency = recoveryScore >= 70 ? 4 : 3;
    suggestion = recoveryScore >= 70
      ? `Восстановление хорошее (${recoveryScore}%) — 4 тренировки/нед оптимально для силы.`
      : `Восстановление ${recoveryScore}% — 3 тренировки/нед безопаснее для силовых занятий.`;
  } else if (userGoal === 'MUSCLE_GAIN') {
    suggestedFrequency = recoveryScore >= 60 ? 5 : 4;
    suggestion = recoveryScore >= 60
      ? `Для гипертрофии 5 тренировок/нед даст больше стимула.`
      : `Восстановление ${recoveryScore}% — 4 тренировки/нед для баланса роста и отдыха.`;
  } else if (userGoal === 'WEIGHT_LOSS') {
    suggestedFrequency = recoveryScore >= 50 ? 5 : 4;
    suggestion = `Для жиросжигания ${suggestedFrequency} тренировок/нед + повседневная активность.`;
  } else {
    suggestedFrequency = recoveryScore >= 65 ? 4 : 3;
    suggestion = `Оптимально ${suggestedFrequency} тренировок/нед при текущем восстановлении (${recoveryScore}%).`;
  }

  const freqDiff = Math.abs(currentFrequency - suggestedFrequency);
  if (freqDiff < 0.5) return ''; // Already optimal, no need to suggest

  return `\n\n## 📅 ЧАСТОТА ТРЕНИРОВОК
Текущая: ${currentFrequency} тренировок/нед | Рекомендуемая: ${suggestedFrequency}/нед
${suggestion}
${currentFrequency > suggestedFrequency + 0.5 ? '→ Больше отдыха — лучше прогресс. Качество > количество.' : ''}
${currentFrequency < suggestedFrequency - 0.5 ? '→ Можно добавить тренировку — восстановление позволяет.' : ''}`;
}

// ─── Block 38: Nutrition Gap Detector ───────────────────────────────────────
// Detect potential micronutrient gaps from meal patterns

function detectNutritionGaps(
  meals: Array<{ items: Array<{ name: string; protein: number; fats: number; carbs: number }> }>,
  userGoal: string | null,
): string {
  if (meals.length < 3) return ''; // Need at least 3 meals for analysis

  // Collect all food items
  const allItems = meals.flatMap((m) => m.items.map((i) => i.name.toLowerCase()));

  const gaps: string[] = [];
  const recommendations: string[] = [];

  // Check for protein source variety
  const proteinSources = allItems.filter((name) =>
    /курица|мясо|рыба|говядин|свинин|яйц|творог|тунец|лосось|индейк|печен/i.test(name)
  );
  if (proteinSources.length < meals.length * 0.3) {
    gaps.push('Мало белковых продуктов');
    recommendations.push('Добавь белок в каждый приём: курица, рыба, яйца, творог.');
  }

  // Check for vegetables/fiber
  const veggies = allItems.filter((name) =>
    /салат|овощ|помидор|огурец|брокколи|шпинат|капуст|морков|свекл|перец|лук|зелен|кабачок/i.test(name)
  );
  if (veggies.length < meals.length * 0.2) {
    gaps.push('Мало овощей и клетчатки');
    recommendations.push('Минимум 400г овощей в день для клетчатки и микроэлементов.');
  }

  // Check for healthy fats
  const healthyFats = allItems.filter((name) =>
    /авокадо|орех|миндаль|лосось|масло.*олив|семена|льн/i.test(name)
  );
  if (healthyFats.length === 0) {
    gaps.push('Мало полезных жиров');
    recommendations.push('Добавь источники омега-3: лосось, орехи, семена, авокадо.');
  }

  // Check for dairy/calcium
  const dairy = allItems.filter((name) =>
    /молок|кефир|творог|йогурт|сыр|ряженк/i.test(name)
  );
  if (dairy.length === 0) {
    gaps.push('Мало кальция (нет молочных)');
    recommendations.push('Для костей и мышц: творог, кефир или йогурт ежедневно.');
  }

  // Check carb quality
  const simpleCarbs = allItems.filter((name) =>
    /сахар|конфет|торт|печень.*сладк|шоколад|газировк|сок.*пакет/i.test(name)
  );
  const complexCarbs = allItems.filter((name) =>
    /рис|гречк|овсянк|картофел|макарон|хлеб.*цельнозерн|булгур|киноа|перловк/i.test(name)
  );
  if (simpleCarbs.length > complexCarbs.length && simpleCarbs.length >= 2) {
    gaps.push('Преобладают простые углеводы');
    recommendations.push('Замени сладкое на сложные углеводы: гречка, рис, овсянка.');
  }

  // Goal-specific
  if (userGoal === 'MUSCLE_GAIN') {
    const totalProtein = meals.reduce((s, m) => s + m.items.reduce((ps, i) => ps + i.protein, 0), 0);
    const avgProteinPerMeal = totalProtein / meals.length;
    if (avgProteinPerMeal < 25) {
      gaps.push('Мало белка на приём пищи');
      recommendations.push('Для набора массы: минимум 30г белка в каждом приёме пищи.');
    }
  }

  if (gaps.length === 0) return '';

  return `\n\n## 🥗 ПРОБЕЛЫ В ПИТАНИИ
${gaps.map((g) => `- ❌ ${g}`).join('\n')}
Рекомендации:
${recommendations.map((r) => `- 💡 ${r}`).join('\n')}
→ Если пользователь обсуждает питание — мягко предложи улучшения.`;
}

// ─── Block 39: Workout Template Matcher ─────────────────────────────────────
// Find similar workouts from history to suggest when user asks for ideas

function findSimilarWorkouts(
  historyWorkouts: Array<{ name: string; exercises: Array<{ exercise: { name: string; primaryMuscles: string[] } }>; completedAt: Date | null; totalVolume: number | null }>,
  targetMuscles?: string[],
): string {
  if (historyWorkouts.length < 2) return '';

  // Group workouts by primary muscle focus
  const workoutsByFocus = new Map<string, typeof historyWorkouts>();
  for (const w of historyWorkouts) {
    const muscles = w.exercises.flatMap((e) => e.exercise.primaryMuscles);
    const primary = muscles.sort((a, b) =>
      muscles.filter((m) => m === b).length - muscles.filter((m) => m === a).length
    )[0];
    if (primary) {
      if (!workoutsByFocus.has(primary)) workoutsByFocus.set(primary, []);
      workoutsByFocus.get(primary)!.push(w);
    }
  }

  // Build template summary — most productive workouts per muscle group
  const templates: string[] = [];
  for (const [muscle, workouts] of workoutsByFocus) {
    const best = workouts
      .filter((w) => w.totalVolume && w.totalVolume > 0)
      .sort((a, b) => (b.totalVolume || 0) - (a.totalVolume || 0))[0];
    if (best) {
      const exercises = best.exercises.slice(0, 4).map((e) => e.exercise.name).join(', ');
      templates.push(`${muscle}: "${best.name}" (${exercises}) — ${best.totalVolume} кг объём`);
    }
  }

  if (templates.length === 0) return '';

  return `\n\n## 📋 ЛУЧШИЕ ТРЕНИРОВКИ ИЗ ИСТОРИИ
${templates.slice(0, 5).join('\n')}
→ Используй как референс при составлении новых тренировок или когда пользователь просит идеи.`;
}

// ─── Block 40: Conversational Memory Summary ────────────────────────────────
// Periodically extract and summarize key themes from recent chat history

function summarizeChatThemes(
  recentMessages: Array<{ role: string; content: string }>,
): string {
  if (recentMessages.length < 4) return '';

  const userMessages = recentMessages.filter((m) => m.role === 'user').map((m) => m.content.toLowerCase());

  const themes: string[] = [];

  // Detect recurring topics
  const topicCounts: Record<string, number> = {};
  const topicPatterns: Record<string, RegExp> = {
    'питание': /питани|еда|калори|белок|кбжу|диет|перекус|завтрак|обед|ужин/,
    'тренировки': /тренировк|упражнен|подход|повтор|сет|программ|план/,
    'боль/травма': /болит|боль|травм|повредил|дискомфорт/,
    'мотивация': /мотивац|лень|устал|не хочу|бросить|настроен/,
    'вес тела': /вес|похуд|набор|масс|сушк/,
    'техника': /техник|как делать|правильно|форма|ошибк/,
    'программа': /программ|сплит|план|расписан|график/,
    'добавки': /добавк|протеин.*порош|креатин|витамин|бад/,
    'сон': /сон|спать|бессонниц|высыпа/,
    'стресс': /стресс|нервнич|тревог|психолог/,
  };

  for (const msg of userMessages) {
    for (const [topic, pattern] of Object.entries(topicPatterns)) {
      if (pattern.test(msg)) {
        topicCounts[topic] = (topicCounts[topic] || 0) + 1;
      }
    }
  }

  // Topics mentioned 2+ times are "themes"
  for (const [topic, count] of Object.entries(topicCounts)) {
    if (count >= 2) {
      themes.push(`${topic} (${count}× за сессию)`);
    }
  }

  if (themes.length === 0) return '';

  return `\n\n## 💬 ТЕМЫ РАЗГОВОРА
Пользователь чаще всего обсуждает: ${themes.join(', ')}
→ Приоритизируй эти темы в ответах. Проактивно предлагай помощь по ним.`;
}

// ─── Block 41: Plateau Breaker ──────────────────────────────────────────────
// When overload data shows plateaus, suggest specific science-based strategies

interface PlateauStrategy {
  exerciseName: string;
  strategy: string;
  explanation: string;
}

function getPlateauBreakers(
  overloadData: OverloadStatus[],
): PlateauStrategy[] {
  const plateaus = overloadData.filter((o) => o.status === 'plateau' || o.status === 'regressing');
  if (plateaus.length === 0) return [];

  const strategies: PlateauStrategy[] = [];

  for (const p of plateaus.slice(0, 3)) {
    const strats: Array<{ strategy: string; explanation: string }> = [];
    const lastWeight = p.lastWeights.length > 0 ? p.lastWeights[p.lastWeights.length - 1] : 0;

    if (lastWeight === 0) continue;

    // Strategy 1: Vary rep range
    strats.push({
      strategy: `Переключись на другой диапазон повторений с весом ${Math.round(lastWeight * 0.8)} кг на 2-3 недели`,
      explanation: 'Смена диапазона повторений создаёт новый стимул для адаптации.',
    });

    // Strategy 2: Pause reps
    strats.push({
      strategy: `Добавь паузу 2 сек в нижней точке: ${Math.round(lastWeight * 0.85)} кг × 3-4 подхода`,
      explanation: 'Паузы убирают инерцию и увеличивают время под нагрузкой.',
    });

    // Strategy 3: Volume manipulation
    if (p.status === 'regressing') {
      strats.push({
        strategy: `Снизь объём на 40% на 1 неделю (deload), затем вернись к ${lastWeight} кг`,
        explanation: 'Регресс часто вызван накопленной усталостью. Суперкомпенсация после deload.',
      });
    } else {
      strats.push({
        strategy: `Добавь 1 дополнительный подход к ${p.exercise} на 2 недели`,
        explanation: 'Кратковременное повышение объёма может преодолеть адаптационное плато.',
      });
    }

    // Pick best 2 strategies
    const selected = strats.slice(0, 2);
    for (const s of selected) {
      strategies.push({ exerciseName: p.exercise, ...s });
    }
  }

  return strategies;
}

function buildPlateauContext(strategies: PlateauStrategy[]): string {
  if (strategies.length === 0) return '';

  const grouped = new Map<string, PlateauStrategy[]>();
  for (const s of strategies) {
    if (!grouped.has(s.exerciseName)) grouped.set(s.exerciseName, []);
    grouped.get(s.exerciseName)!.push(s);
  }

  const lines: string[] = [];
  for (const [exercise, strats] of grouped) {
    lines.push(`**${exercise}** (плато):`);
    for (const s of strats) {
      lines.push(`  → ${s.strategy} — ${s.explanation}`);
    }
  }

  return `\n\n## 🧱 СТРАТЕГИИ ПРЕОДОЛЕНИЯ ПЛАТО
${lines.join('\n')}
→ Предлагай эти стратегии когда пользователь жалуется на застой или спрашивает как прогрессировать.`;
}

// ─── Block 42: Sleep & Recovery Questionnaire ───────────────────────────────
// Proactive lifestyle questions when recovery is suboptimal

function buildRecoveryQuestionnaire(
  recoveryScore: number,
  hasAskedAboutSleep: boolean, // from AI memory
  fatigueStatus: string,
): string {
  if (recoveryScore >= 75 && fatigueStatus !== 'overreaching' && fatigueStatus !== 'dangerous') return '';

  const questions: string[] = [];

  if (!hasAskedAboutSleep) {
    questions.push('💤 Сколько часов ты обычно спишь? Ложишься/встаёшь в одно время?');
  }

  if (recoveryScore < 50) {
    questions.push('😰 Уровень стресса на работе/учёбе по шкале 1-10?');
    questions.push('💧 Сколько воды пьёшь в день?');
  }

  if (fatigueStatus === 'overreaching' || fatigueStatus === 'dangerous') {
    questions.push('🤕 Есть ли болезненность в суставах или мышцах, которая не проходит?');
    questions.push('📉 Заметил снижение мотивации или настроения?');
  }

  if (questions.length === 0) return '';

  return `\n\n## 🩺 ВОПРОСЫ О ВОССТАНОВЛЕНИИ (задай 1-2 если контекст подходит)
${questions.slice(0, 3).join('\n')}
→ Восстановление ${recoveryScore}%, усталость: ${fatigueStatus}. Нужна диагностика.`;
}

// ─── Block 43: Progressive Overload Planner ─────────────────────────────────
// Generate concrete week-by-week progression for key exercises

function buildProgressionPlan(
  overloadData: OverloadStatus[],
  userGoal: string | null,
): string {
  const progressing = overloadData.filter((o) => o.status === 'progressing' || o.status === 'plateau');
  if (progressing.length === 0) return '';

  const plans: string[] = [];

  for (const ex of progressing.slice(0, 3)) {
    let plan: string;
    const lastWeight = ex.lastWeights.length > 0 ? ex.lastWeights[ex.lastWeights.length - 1] : 0;
    if (lastWeight === 0) continue;

    if (userGoal === 'STRENGTH') {
      const w1 = lastWeight;
      const w2 = w1 + 2.5;
      const w3 = w2 + 2.5;
      const w4 = Math.round(w1 * 0.6 / 2.5) * 2.5;
      plan = `${ex.exercise}: нед1 ${w1}кг×5×4 → нед2 ${w2}кг×4×4 → нед3 ${w3}кг×3×4 → нед4 ${w4}кг×8×3 (deload)`;
    } else if (userGoal === 'MUSCLE_GAIN') {
      const nextWeight = lastWeight + 2.5;
      plan = `${ex.exercise}: нед1-2 ${lastWeight}кг×10-12×4 (больше повторов) → нед3-4 ${nextWeight}кг×8×4 (больше вес)`;
    } else {
      plan = `${ex.exercise}: +2.5 кг каждые 1-2 недели при выполнении всех подходов`;
    }

    plans.push(plan);
  }

  return `\n\n## 📐 ПЛАН ПРОГРЕССИИ (ближайшие 4 недели)
${plans.join('\n')}
→ Предлагай этот план когда пользователь спрашивает про прогресс или веса.`;
}

// ─── Block 44: Response Quality Guard ───────────────────────────────────────
// Post-processing to ensure AI response meets quality standards

function validateAIResponse(response: string, intent: string): { cleaned: string; warnings: string[] } {
  let cleaned = response;
  const warnings: string[] = [];

  // Remove excessive emoji (more than 8 per response)
  const emojiCount = (cleaned.match(/[\p{Emoji_Presentation}\p{Extended_Pictographic}]/gu) || []).length;
  if (emojiCount > 8) {
    warnings.push('excessive_emoji');
    // Remove emojis beyond first 5
    let count = 0;
    cleaned = cleaned.replace(/[\p{Emoji_Presentation}\p{Extended_Pictographic}]/gu, (match) => {
      count++;
      return count <= 5 ? match : '';
    });
  }

  // Remove English text blocks (AI sometimes responds in English)
  const englishPattern = /^[A-Za-z\s,.!?:;'"()-]{50,}$/m;
  if (englishPattern.test(cleaned) && intent !== 'technique_question') {
    warnings.push('english_detected');
  }

  // Ensure response isn't too short for important intents
  if (cleaned.length < 30 && !['greeting'].includes(intent)) {
    warnings.push('too_short');
  }

  // Ensure response isn't absurdly long
  if (cleaned.length > 3000) {
    warnings.push('too_long');
    // Trim at last sentence break before 3000 chars
    const trimPoint = cleaned.lastIndexOf('.', 2800);
    if (trimPoint > 1500) {
      cleaned = cleaned.substring(0, trimPoint + 1);
    }
  }

  // Remove repeated sentences
  const sentences = cleaned.split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const s of sentences) {
    const normalized = s.toLowerCase().replace(/\s+/g, ' ');
    if (!seen.has(normalized)) {
      seen.add(normalized);
      unique.push(s);
    }
  }
  if (unique.length < sentences.length) {
    warnings.push('duplicates_removed');
    // Reconstruct — find original sentence endings
    cleaned = unique.join('. ') + '.';
  }

  return { cleaned, warnings };
}

// ─── Block 45: Workout Intensity Zones ──────────────────────────────────────
// RPE-based intensity zone recommendations for different training phases

function buildIntensityZoneContext(
  userGoal: string | null,
  currentPhase: string, // from periodization
  avgRpe: number | null,
): string {
  if (!userGoal) return '';

  interface Zone {
    name: string;
    rpeRange: string;
    percentRM: string;
    purpose: string;
  }

  const zones: Zone[] = [
    { name: 'Лёгкая', rpeRange: '4-5', percentRM: '50-65%', purpose: 'Разминка, техника, активное восстановление' },
    { name: 'Умеренная', rpeRange: '6-7', percentRM: '65-75%', purpose: 'Объёмная работа, гипертрофия, выносливость' },
    { name: 'Тяжёлая', rpeRange: '8-9', percentRM: '75-90%', purpose: 'Сила, мышечный рост, прогрессия' },
    { name: 'Максимальная', rpeRange: '9.5-10', percentRM: '90-100%', purpose: 'Пиковая сила, тестирование 1ПМ' },
  ];

  let targetZone: string;
  let distribution: string;

  if (currentPhase === 'accumulation') {
    targetZone = 'Умеренная-Тяжёлая (RPE 6-8)';
    distribution = '60% умеренная, 30% тяжёлая, 10% лёгкая';
  } else if (currentPhase === 'intensification') {
    targetZone = 'Тяжёлая (RPE 8-9)';
    distribution = '20% умеренная, 60% тяжёлая, 20% максимальная';
  } else if (currentPhase === 'deload') {
    targetZone = 'Лёгкая-Умеренная (RPE 4-6)';
    distribution = '60% лёгкая, 40% умеренная';
  } else {
    // Default based on goal
    if (userGoal === 'STRENGTH') {
      targetZone = 'Тяжёлая (RPE 7-9)';
      distribution = '30% умеренная, 60% тяжёлая, 10% максимальная';
    } else if (userGoal === 'MUSCLE_GAIN') {
      targetZone = 'Умеренная-Тяжёлая (RPE 7-8)';
      distribution = '20% лёгкая, 50% умеренная, 30% тяжёлая';
    } else if (userGoal === 'WEIGHT_LOSS') {
      targetZone = 'Умеренная (RPE 6-7)';
      distribution = '30% лёгкая, 60% умеренная, 10% тяжёлая';
    } else {
      targetZone = 'Умеренная (RPE 6-8)';
      distribution = '20% лёгкая, 60% умеренная, 20% тяжёлая';
    }
  }

  let rpeWarning = '';
  if (avgRpe !== null) {
    if (avgRpe >= 9 && currentPhase !== 'intensification') {
      rpeWarning = `\n⚠️ Средний RPE ${avgRpe} — слишком высокий для текущей фазы. Снизь интенсивность.`;
    } else if (avgRpe < 6 && currentPhase !== 'deload') {
      rpeWarning = `\n💡 Средний RPE ${avgRpe} — можно работать тяжелее для лучшего прогресса.`;
    }
  }

  return `\n\n## 🎚 ЗОНЫ ИНТЕНСИВНОСТИ
Целевая зона: ${targetZone}
Распределение: ${distribution}${rpeWarning}
→ Используй при программировании нагрузки и ответах о весах.`;
}

// ─── Block 46: Warm-up Generator ────────────────────────────────────────────
// Suggest specific warm-up exercises based on today's planned workout

const WARMUP_TEMPLATES: Record<string, string[]> = {
  chest: ['Круговые вращения руками (20 раз)', 'Отжимания от стены (10 раз)', 'Пуловер с лёгкой гантелей (12 раз)', 'Жим пустым грифом (15 раз)'],
  back: ['Вис на перекладине (15 сек)', 'Круговые вращения плечами (15 раз)', 'Тяга резинки к лицу (15 раз)', 'Гиперэкстензия без веса (12 раз)'],
  shoulders: ['Круговые вращения руками (20 раз)', 'Y-W-T подъёмы лёжа (10 каждый)', 'Вращения с резинкой (15 раз)', 'Жим гантелей 2-3 кг (12 раз)'],
  quadriceps: ['Ходьба на месте (60 сек)', 'Воздушные приседания (15 раз)', 'Выпады без веса (10 на каждую)', 'Разгибания ног без веса (15 раз)'],
  hamstrings: ['Наклоны вперёд (10 раз)', 'Румынская тяга без веса (12 раз)', 'Махи ногой назад (10 раз)', 'Ходьба на месте с высоким подъёмом колена (30 сек)'],
  glutes: ['Ягодичный мостик (15 раз)', 'Отведение бедра стоя (12 раз)', 'Приседания в стиле сумо без веса (12 раз)'],
  biceps: ['Сгибания рук без веса (20 раз)', 'Вращения запястий (15 раз)', 'Сгибания с лёгкой гантелей (12 раз)'],
  triceps: ['Разгибания рук над головой без веса (15 раз)', 'Отжимания от скамьи (10 раз)', 'Вращения в локтевых суставах (15 раз)'],
};

function generateWarmup(primaryMuscles: string[]): string {
  if (primaryMuscles.length === 0) return '';

  const warmupExercises: string[] = [
    '🏃 Общая разминка: 5 мин лёгкого кардио (ходьба, велотренажёр, скакалка)',
  ];

  const usedMuscles = new Set<string>();
  for (const muscle of primaryMuscles) {
    const normalized = muscle.toLowerCase();
    for (const [key, exercises] of Object.entries(WARMUP_TEMPLATES)) {
      if (normalized.includes(key) && !usedMuscles.has(key)) {
        usedMuscles.add(key);
        warmupExercises.push(`🎯 ${key}: ${exercises.slice(0, 2).join(', ')}`);
      }
    }
  }

  if (warmupExercises.length <= 1) return '';

  return `\n\n## 🔥 РЕКОМЕНДУЕМАЯ РАЗМИНКА
${warmupExercises.join('\n')}
→ Предлагай разминку когда пользователь начинает тренировку или спрашивает о ней.`;
}

// ─── Block 47: Body Composition Estimator ───────────────────────────────────
// Rough body fat % estimation from weight trends and Navy method approximation

function estimateBodyComposition(
  user: { weightKg?: number | null; heightCm?: number | null; gender?: string | null },
  bodyWeightHistory: Array<{ weightKg: number; date: Date }>,
  totalWorkoutsLast30Days: number,
): string {
  if (!user.weightKg || !user.heightCm || bodyWeightHistory.length < 2) return '';

  const bmi = user.weightKg / Math.pow(user.heightCm / 100, 2);

  // Simple BF% estimation from BMI (Deurenberg formula, rough approximation)
  // BF% = 1.2 × BMI + 0.23 × age − 10.8 × sex − 5.4
  // Without age, use simplified version
  const sexFactor = user.gender === 'MALE' ? 1 : 0;
  const estimatedBF = Math.round(1.2 * bmi - 10.8 * sexFactor - 5.4 + 0.23 * 25); // assume ~25 age

  // Categorize
  let category: string;
  if (user.gender === 'MALE') {
    if (estimatedBF < 10) category = 'соревновательная форма';
    else if (estimatedBF < 15) category = 'атлетичная форма';
    else if (estimatedBF < 20) category = 'нормальный уровень';
    else if (estimatedBF < 25) category = 'выше нормы';
    else category = 'избыточный';
  } else {
    if (estimatedBF < 18) category = 'соревновательная форма';
    else if (estimatedBF < 23) category = 'атлетичная форма';
    else if (estimatedBF < 28) category = 'нормальный уровень';
    else if (estimatedBF < 33) category = 'выше нормы';
    else category = 'избыточный';
  }

  // Weight trend over last month
  const newest = bodyWeightHistory[0];
  const monthAgo = bodyWeightHistory.find(
    (bw) => (Date.now() - new Date(bw.date).getTime()) / (1000 * 60 * 60 * 24) >= 21
  );
  let trendNote = '';
  if (monthAgo) {
    const delta = newest.weightKg - monthAgo.weightKg;
    if (Math.abs(delta) > 0.5) {
      trendNote = `\nДинамика за месяц: ${delta > 0 ? '+' : ''}${delta.toFixed(1)} кг`;
    }
  }

  return `\n\n## 📐 СОСТАВ ТЕЛА (оценка)
BMI: ${bmi.toFixed(1)} | Примерный % жира: ~${estimatedBF}% (${category})
Вес: ${user.weightKg} кг, Рост: ${user.heightCm} см${trendNote}
⚠️ Это грубая оценка по BMI. Для точности рекомендуй калиперометрию или биоимпедансометрию.
→ Используй при обсуждении целей по составу тела.`;
}

// ─── Block 48: Supplement Timing Advisor ────────────────────────────────────
// Recommend supplement timing based on training schedule and goals

function buildSupplementAdvice(
  userGoal: string | null,
  hasWorkoutToday: boolean,
  hour: number,
): string {
  if (!userGoal) return '';

  const advice: string[] = [];

  // Universal: creatine
  advice.push('💊 Креатин: 5г ежедневно, в любое время (с едой для лучшего усвоения)');

  // Protein timing
  if (hasWorkoutToday) {
    if (hour < 12) {
      advice.push('🥤 Протеин: 25-30г в течение 2ч после тренировки (сывороточный)');
    } else {
      advice.push('🥤 Протеин: 25-30г после тренировки + казеин перед сном');
    }
  } else {
    advice.push('🥤 Протеин: распредели равномерно по приёмам пищи (30г каждый)');
  }

  // Goal-specific
  if (userGoal === 'WEIGHT_LOSS') {
    advice.push('🔥 Перед тренировкой: кофеин (200мг) за 30 мин для повышения метаболизма');
    advice.push('🥬 Витамин D: 2000-4000 МЕ с жирной пищей (часто дефицит в РФ)');
  } else if (userGoal === 'MUSCLE_GAIN') {
    advice.push('🍌 До тренировки: 30-40г углеводов за 1-2ч для энергии');
    advice.push('💧 Во время тренировки: BCAA или EAA (5-10г) если тренируешься натощак');
  } else if (userGoal === 'STRENGTH') {
    advice.push('⚡ До тренировки: кофеин (3-6 мг/кг) за 30-60 мин для силовых показателей');
    advice.push('🧂 Электролиты: при длительных тренировках (>60 мин) — натрий + калий');
  }

  // Season-specific for Russia
  const month = new Date().getMonth();
  if (month >= 9 || month <= 3) {
    advice.push('☀️ Витамин D: 2000-4000 МЕ/день (октябрь-март — мало солнца в РФ)');
  }

  return `\n\n## 💊 РЕКОМЕНДАЦИИ ПО ДОБАВКАМ
${advice.slice(0, 4).join('\n')}
→ Упоминай при обсуждении питания или восстановления. Это общие рекомендации, не медицинский совет.`;
}

// ─── Block 49: Workout Comparison ───────────────────────────────────────────
// Compare current week vs previous week performance

function buildWorkoutComparison(
  thisWeekVolume: number,
  prevWeekVolume: number,
  thisWeekCount: number,
  prevWeekCount: number,
  thisWeekDuration: number,
  prevWeekDuration: number,
): string {
  if (thisWeekVolume === 0 && prevWeekVolume === 0) return '';
  if (prevWeekVolume === 0) return ''; // nothing to compare

  const volumeDelta = thisWeekVolume - prevWeekVolume;
  const volumePct = Math.round((volumeDelta / prevWeekVolume) * 100);
  const countDelta = thisWeekCount - prevWeekCount;
  const durationDelta = thisWeekDuration - prevWeekDuration;

  const lines: string[] = [];
  lines.push(`Объём: ${Math.round(thisWeekVolume)} кг ${volumeDelta >= 0 ? '📈' : '📉'} (${volumeDelta >= 0 ? '+' : ''}${volumePct}%)`);
  lines.push(`Тренировок: ${thisWeekCount} ${countDelta > 0 ? `(+${countDelta})` : countDelta < 0 ? `(${countDelta})` : '(=)'}`);
  if (thisWeekDuration > 0 && prevWeekDuration > 0) {
    lines.push(`Длительность: ${thisWeekDuration} мин ${durationDelta > 0 ? `(+${durationDelta})` : durationDelta < 0 ? `(${durationDelta})` : '(=)'}`);
  }

  let verdict = '';
  if (volumePct > 10 && thisWeekCount >= prevWeekCount) verdict = '✅ Прогресс! Объём растёт — хорошая динамика.';
  else if (volumePct < -15) verdict = '⚠️ Объём упал. Это может быть деload (хорошо) или потеря мотивации (плохо).';
  else if (volumePct >= -5 && volumePct <= 5) verdict = '➡️ Стабильно. Для прогресса увеличивай объём на 5-10% в неделю.';

  return `\n\n## 📊 СРАВНЕНИЕ С ПРОШЛОЙ НЕДЕЛЕЙ
${lines.join('\n')}
${verdict}`;
}

// ─── Block 50: Context Size Optimizer ───────────────────────────────────────
// Smart pruning of system prompt sections based on intent relevance

interface ContextSection {
  name: string;
  content: string;
  relevantIntents: Set<string>;
  priority: number; // 1 = always include, 2 = include if relevant, 3 = include if space allows
}

function optimizeContext(
  sections: ContextSection[],
  intent: string,
  maxTokenEstimate: number,
): string[] {
  // Sort by priority, then by relevance
  const scored = sections.map((s) => ({
    ...s,
    score: s.priority * 10 + (s.relevantIntents.has(intent) || s.relevantIntents.has('*') ? 100 : 0),
  }));

  scored.sort((a, b) => b.score - a.score);

  const included: string[] = [];
  let totalTokens = 0;

  for (const section of scored) {
    if (!section.content) continue;
    const sectionTokens = Math.ceil(section.content.length / 3.5); // rough estimate

    if (totalTokens + sectionTokens > maxTokenEstimate) {
      // Skip low-priority sections if over budget
      if (section.priority >= 3) continue;
    }

    included.push(section.content);
    totalTokens += sectionTokens;
  }

  return included;
}

