function getTechniqueCues(exerciseNames: string[]): string {
  if (exerciseNames.length === 0) return '';

  const cues: string[] = [];
  for (const name of exerciseNames) {
    const normalized = name.toLowerCase();
    for (const [exercise, data] of Object.entries(TECHNIQUE_CUES)) {
      if (normalized.includes(exercise) || exercise.includes(normalized)) {
        cues.push(`**${exercise}**: ❌ ${data.mistakes[0]} → ✅ ${data.cues[0]}`);
        if (cues.length >= 3) break;
      }
    }
    if (cues.length >= 3) break;
  }

  if (cues.length === 0) return '';

  return `\n\n## 🎯 ТЕХНИКА — ЧАСТЫЕ ОШИБКИ
${cues.join('\n')}
→ Упоминай при обсуждении техники или когда пользователь делает эти упражнения.`;
}

// ─── Block 52: Sleep Quality Estimator ──────────────────────────────────────
// Infer likely sleep quality from workout performance patterns

function estimateSleepQuality(
  recentWorkouts: Array<{
    completedAt: Date | null;
    totalVolume: number | null;
    durationMinutes: number | null;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  const completedWithTime = recentWorkouts
    .filter((w) => w.completedAt)
    .map((w) => ({
      hour: new Date(w.completedAt!).getHours(),
      volume: w.totalVolume || 0,
      duration: w.durationMinutes || 0,
    }));

  if (completedWithTime.length < 3) return '';

  // Detect late-night training pattern (after 22:00)
  const lateWorkouts = completedWithTime.filter((w) => w.hour >= 22 || w.hour < 5);
  const lateRatio = lateWorkouts.length / completedWithTime.length;

  // Detect inconsistent training times (high variance in start hour)
  const hours = completedWithTime.map((w) => w.hour);
  const avgHour = hours.reduce((a, b) => a + b, 0) / hours.length;
  const hourVariance = hours.reduce((sum, h) => sum + Math.pow(h - avgHour, 2), 0) / hours.length;

  // Detect performance dips (declining volume over consecutive workouts)
  const volumes = completedWithTime.map((w) => w.volume);
  let consecutiveDeclines = 0;
  for (let i = 1; i < Math.min(volumes.length, 5); i++) {
    if (volumes[i - 1] > 0 && volumes[i] < volumes[i - 1] * 0.85) consecutiveDeclines++;
  }

  const warnings: string[] = [];

  if (lateRatio > 0.3) {
    warnings.push('🌙 Частые тренировки поздно вечером (>22:00) — могут ухудшать качество сна');
  }
  if (hourVariance > 20) {
    warnings.push('🔀 Сильно «плавающее» время тренировок — нестабильный режим может влиять на сон');
  }
  if (consecutiveDeclines >= 2) {
    warnings.push('📉 Падение объёма в последних тренировках — возможный признак недосыпа');
  }

  if (warnings.length === 0) return '';

  return `\n\n## 😴 КАЧЕСТВО СНА (косвенная оценка)
${warnings.join('\n')}
→ Если уместно, спроси пользователя о режиме сна. Рекомендуй 7-9 часов, стабильный график, тренировки не позже чем за 2ч до сна.`;
}

// ─── Block 53: Muscle Recovery Tracker ──────────────────────────────────────
// Estimate per-muscle-group recovery status based on last workout date

interface MuscleRecoveryStatus {
  muscle: string;
  hoursSinceTraining: number;
  status: 'fresh' | 'recovering' | 'recovered' | 'detraining';
  readyToTrain: boolean;
}

const RECOVERY_HOURS: Record<string, number> = {
  chest: 48, back: 48, shoulders: 48, quadriceps: 72,
  hamstrings: 72, glutes: 48, biceps: 36, triceps: 36,
  abs: 24, calves: 24, traps: 48, lats: 48,
  forearms: 24, lower_back: 72,
};

function trackMuscleRecovery(
  recentWorkouts: Array<{
    completedAt: Date | null;
    exercises: Array<{ exercise: { primaryMuscles: string[] } }>;
  }>,
): MuscleRecoveryStatus[] {
  const muscleLastTrained: Record<string, Date> = {};

  for (const workout of recentWorkouts) {
    if (!workout.completedAt) continue;
    const completedDate = new Date(workout.completedAt);
    for (const ex of workout.exercises) {
      for (const muscle of ex.exercise.primaryMuscles) {
        const m = muscle.toLowerCase();
        if (!muscleLastTrained[m] || completedDate > muscleLastTrained[m]) {
          muscleLastTrained[m] = completedDate;
        }
      }
    }
  }

  const now = Date.now();
  const results: MuscleRecoveryStatus[] = [];

  for (const [muscle, lastDate] of Object.entries(muscleLastTrained)) {
    const hoursSince = (now - lastDate.getTime()) / (1000 * 60 * 60);
    const recoveryTime = RECOVERY_HOURS[muscle] || 48;

    let status: MuscleRecoveryStatus['status'];
    if (hoursSince < 12) status = 'fresh';
    else if (hoursSince < recoveryTime) status = 'recovering';
    else if (hoursSince < recoveryTime * 3) status = 'recovered';
    else status = 'detraining';

    results.push({
      muscle,
      hoursSinceTraining: Math.round(hoursSince),
      status,
      readyToTrain: hoursSince >= recoveryTime,
    });
  }

  return results.sort((a, b) => a.hoursSinceTraining - b.hoursSinceTraining);
}

function buildMuscleRecoveryContext(statuses: MuscleRecoveryStatus[]): string {
  if (statuses.length === 0) return '';

  const recovering = statuses.filter((s) => s.status === 'recovering');
  const recovered = statuses.filter((s) => s.status === 'recovered');
  const detraining = statuses.filter((s) => s.status === 'detraining');

  const lines: string[] = [];
  if (recovering.length > 0) {
    lines.push(`⏳ Восстанавливаются: ${recovering.map((s) => `${s.muscle} (${s.hoursSinceTraining}ч)`).join(', ')}`);
  }
  if (recovered.length > 0) {
    lines.push(`✅ Готовы к тренировке: ${recovered.map((s) => s.muscle).join(', ')}`);
  }
  if (detraining.length > 0) {
    lines.push(`⚠️ Давно не тренированы: ${detraining.map((s) => `${s.muscle} (${Math.round(s.hoursSinceTraining / 24)}д)`).join(', ')}`);
  }

  if (lines.length === 0) return '';

  return `\n\n## 💪 ВОССТАНОВЛЕНИЕ МЫШЦ
${lines.join('\n')}
→ Учитывай при рекомендации тренировки на сегодня. Не предлагай нагружать восстанавливающиеся мышцы.`;
}

// ─── Block 54: Workout Streak Motivator ─────────────────────────────────────
// Dynamic motivational context based on current streak and milestones

function buildStreakMotivation(streak: number, totalWorkouts: number): string {
  if (streak <= 0 && totalWorkouts <= 0) return '';

  const lines: string[] = [];

  // Streak-based motivation
  if (streak === 0) {
    lines.push('🔄 Серия прервана. Мотивируй вернуться: «Каждый чемпион пропускал тренировки, но возвращался».');
  } else if (streak <= 3) {
    lines.push(`🔥 Серия: ${streak} ${streak === 1 ? 'тренировка' : streak <= 4 ? 'тренировки' : 'тренировок'}. Поддержи: «Отличное начало, продолжай!»`);
  } else if (streak <= 7) {
    lines.push(`🔥🔥 Серия: ${streak} тренировок! «Ты на волне! Неделя стабильных тренировок — это серьёзно.»`);
  } else if (streak <= 14) {
    lines.push(`🔥🔥🔥 Серия: ${streak} тренировок! «Две недели подряд — привычка формируется. Ты молодец!»`);
  } else if (streak <= 30) {
    lines.push(`🏆 Серия: ${streak} тренировок! «Месяц регулярных тренировок — это уже образ жизни!»`);
  } else {
    lines.push(`👑 СЕРИЯ: ${streak} тренировок! «${streak} тренировок подряд — ты железный! Такая дисциплина вдохновляет.»`);
  }

  // Milestone motivation
  const milestones = [10, 25, 50, 100, 200, 365, 500];
  for (const m of milestones) {
    if (totalWorkouts >= m - 2 && totalWorkouts <= m) {
      lines.push(`🎯 Почти ${m} тренировок всего! (сейчас ${totalWorkouts}) — отметь этот момент!`);
      break;
    }
    if (totalWorkouts === m) {
      lines.push(`🎉 ${m} тренировок всего! Поздравь пользователя с этим достижением!`);
      break;
    }
  }

  if (lines.length === 0) return '';

  return `\n\n## 🏅 МОТИВАЦИЯ
${lines.join('\n')}
→ Используй для поддержания мотивации. Не навязывай — вплетай естественно в ответ.`;
}

// ─── Block 55: Training Age Estimator ───────────────────────────────────────
// Estimate training maturity and adjust advice complexity accordingly

function estimateTrainingAge(
  user: { trainingExperienceYears?: number | null; fitnessLevel?: string | null },
  totalWorkoutsInApp: number,
  avgVolume: number,
): string {
  // Calculate effective training age
  let estimatedYears = user.trainingExperienceYears || 0;

  // Adjust based on app usage
  if (totalWorkoutsInApp > 200 && estimatedYears < 2) estimatedYears = Math.max(estimatedYears, 2);
  if (totalWorkoutsInApp > 500 && estimatedYears < 4) estimatedYears = Math.max(estimatedYears, 4);

  // Cross-check with fitness level
  if (user.fitnessLevel === 'EXPERT' && estimatedYears < 3) estimatedYears = 3;
  if (user.fitnessLevel === 'ADVANCED' && estimatedYears < 2) estimatedYears = 2;

  let tier: string;
  let adviceStyle: string;

  if (estimatedYears < 1) {
    tier = 'новичок';
    adviceStyle = 'Объясняй базово, избегай сложной терминологии. Фокус на правильную технику и постепенность. Не перегружай информацией.';
  } else if (estimatedYears < 3) {
    tier = 'средний';
    adviceStyle = 'Можно использовать базовую терминологию (RPE, суперсет, периодизация). Объясняй «почему» за рекомендациями.';
  } else if (estimatedYears < 6) {
    tier = 'опытный';
    adviceStyle = 'Используй продвинутую терминологию свободно. Давай нюансированные советы. Обсуждай стратегии (DUP, блоковая периодизация, авторегуляция).';
  } else {
    tier = 'ветеран';
    adviceStyle = 'Общайся как с коллегой. Обсуждай тонкости (RIR vs RPE, accommodating resistance, velocity-based training). Предлагай продвинутые методики.';
  }

  return `\n\n## 🎓 ТРЕНИРОВОЧНЫЙ ОПЫТ
Оценка: ~${estimatedYears} ${estimatedYears === 1 ? 'год' : estimatedYears < 5 ? 'года' : 'лет'} (${tier})
${adviceStyle}`;
}

// ─── Block 56: Workout Rating Feedback Loop ─────────────────────────────────
// Use workout ratings to adapt future recommendations

function analyzeWorkoutRatings(
  recentWorkouts: Array<{
    name: string;
    rating?: number | null;
    totalVolume: number | null;
    durationMinutes: number | null;
    exercises: Array<{ exercise: { name: string; primaryMuscles: string[] } }>;
  }>,
): string {
  const ratedWorkouts = recentWorkouts.filter((w) => w.rating && w.rating > 0);
  if (ratedWorkouts.length < 2) return '';

  const avgRating = ratedWorkouts.reduce((sum, w) => sum + (w.rating || 0), 0) / ratedWorkouts.length;

  // Find best and worst rated workouts
  const sorted = [...ratedWorkouts].sort((a, b) => (b.rating || 0) - (a.rating || 0));
  const best = sorted[0];
  const worst = sorted[sorted.length - 1];

  const lines: string[] = [];
  lines.push(`Средняя оценка тренировок: ${avgRating.toFixed(1)}/5`);

  if (best && best.rating && best.rating >= 4) {
    const muscles = best.exercises.flatMap((e) => e.exercise.primaryMuscles);
    const uniqueMuscles = [...new Set(muscles)].slice(0, 3);
    lines.push(`👍 Лучшая: "${best.name}" (${best.rating}/5) — ${uniqueMuscles.join(', ')}`);
  }

  if (worst && worst.rating && worst.rating <= 2) {
    lines.push(`👎 Худшая: "${worst.name}" (${worst.rating}/5) — возможно стоит пересмотреть`);
  }

  // Detect trend
  if (ratedWorkouts.length >= 4) {
    const recentAvg = ratedWorkouts.slice(0, 2).reduce((s, w) => s + (w.rating || 0), 0) / 2;
    const olderAvg = ratedWorkouts.slice(-2).reduce((s, w) => s + (w.rating || 0), 0) / 2;
    if (recentAvg - olderAvg >= 0.5) {
      lines.push('📈 Оценки растут — тренировки нравятся всё больше!');
    } else if (olderAvg - recentAvg >= 0.5) {
      lines.push('📉 Оценки падают — стоит обсудить что не нравится и скорректировать программу');
    }
  }

  return `\n\n## ⭐ ОБРАТНАЯ СВЯЗЬ ПО ТРЕНИРОВКАМ
${lines.join('\n')}
→ Используй для адаптации рекомендаций. Больше тренировок, похожих на лучшие. Меньше — на худшие.`;
}

// ─── Block 57: Calorie Burn Estimator ───────────────────────────────────────
// Estimate calories burned per workout from volume, duration, and type

function estimateCaloriesBurned(
  workout: {
    totalVolume: number | null;
    durationMinutes: number | null;
    exercises: Array<{ exercise: { category: string; type: string } }>;
  } | null,
  userWeightKg: number | null,
): string {
  if (!workout || !workout.durationMinutes || !userWeightKg) return '';

  const duration = workout.durationMinutes;
  const weight = userWeightKg;

  // Determine workout intensity from exercise types
  const categories = workout.exercises.map((e) => e.exercise.category);
  const hasCardio = categories.includes('cardio');
  const hasStrength = categories.includes('strength');

  // MET values (rough estimates)
  let met: number;
  if (hasCardio && !hasStrength) {
    met = 7.0; // moderate cardio
  } else if (hasStrength && !hasCardio) {
    met = 5.0; // strength training
  } else if (hasCardio && hasStrength) {
    met = 6.0; // mixed
  } else {
    met = 4.5; // flexibility/functional
  }

  // Adjust for volume (higher volume = more calorie expenditure)
  if (workout.totalVolume && workout.totalVolume > 10000) {
    met += 0.5; // heavy session
  }

  // Calorie estimation: kcal = MET × weight(kg) × duration(hours)
  const calories = Math.round(met * weight * (duration / 60));

  return `\n\n## 🔥 РАСХОД КАЛОРИЙ (последняя тренировка)
Примерно ${calories} ккал за ${duration} мин (MET ~${met.toFixed(1)})
${hasStrength ? '💪 Силовая тренировка сжигает калории ещё 24-48ч после (EPOC-эффект)' : ''}
⚠️ Грубая оценка. Реальный расход зависит от интенсивности, пауз отдыха, ЧСС.`;
}

// ─── Block 58: Exercise Variety Scorer ──────────────────────────────────────
// Detect monotonous routines and suggest adding variety

function scoreExerciseVariety(
  recentWorkouts: Array<{
    exercises: Array<{ exercise: { name: string; type: string } }>;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  // Count exercise frequency across recent workouts
  const exerciseCounts: Record<string, number> = {};
  const typeCounts: Record<string, number> = {};
  let totalExercises = 0;

  for (const w of recentWorkouts) {
    for (const e of w.exercises) {
      exerciseCounts[e.exercise.name] = (exerciseCounts[e.exercise.name] || 0) + 1;
      typeCounts[e.exercise.type] = (typeCounts[e.exercise.type] || 0) + 1;
      totalExercises++;
    }
  }

  const uniqueExercises = Object.keys(exerciseCounts).length;
  const varietyRatio = uniqueExercises / Math.max(totalExercises, 1);

  // Find overused exercises (>60% of workouts)
  const threshold = recentWorkouts.length * 0.6;
  const overused = Object.entries(exerciseCounts)
    .filter(([, count]) => count >= threshold)
    .map(([name]) => name);

  // Find missing equipment types
  const allTypes = ['barbell', 'dumbbell', 'machine', 'cable', 'bodyweight'];
  const missingTypes = allTypes.filter((t) => !typeCounts[t]);

  const lines: string[] = [];

  if (varietyRatio < 0.3) {
    lines.push(`⚠️ Низкое разнообразие упражнений (${uniqueExercises} уникальных из ${totalExercises} всего)`);
  }

  if (overused.length > 0) {
    lines.push(`🔁 Частые упражнения: ${overused.slice(0, 3).join(', ')} — рассмотри замены для новых стимулов`);
  }

  if (missingTypes.length > 0 && missingTypes.length <= 3) {
    const typeNames: Record<string, string> = {
      barbell: 'штанга', dumbbell: 'гантели', machine: 'тренажёры', cable: 'кроссовер', bodyweight: 'собственный вес',
    };
    lines.push(`💡 Не используешь: ${missingTypes.map((t) => typeNames[t] || t).join(', ')} — добавь для баланса`);
  }

  if (lines.length === 0) return '';

  return `\n\n## 🎲 РАЗНООБРАЗИЕ ТРЕНИРОВОК
${lines.join('\n')}
→ Разнообразие стимулов важно для прогресса. Предлагай новые упражнения и снаряды.`;
}

// ─── Block 59: Time-of-Day Performance Analyzer ─────────────────────────────
// Find user's optimal training window from historical performance

function analyzeTrainingTimePerformance(
  workouts: Array<{
    completedAt: Date | null;
    totalVolume: number | null;
    durationMinutes: number | null;
  }>,
): string {
  const withTime = workouts
    .filter((w) => w.completedAt && w.totalVolume && w.totalVolume > 0)
    .map((w) => ({
      hour: new Date(w.completedAt!).getHours(),
      volume: w.totalVolume!,
      duration: w.durationMinutes || 0,
    }));

  if (withTime.length < 5) return '';

  // Group by time slots
  const slots: Record<string, { volumes: number[]; count: number }> = {
    'утро (6-11)': { volumes: [], count: 0 },
    'день (11-16)': { volumes: [], count: 0 },
    'вечер (16-21)': { volumes: [], count: 0 },
    'ночь (21-6)': { volumes: [], count: 0 },
  };

  for (const w of withTime) {
    let slot: string;
    if (w.hour >= 6 && w.hour < 11) slot = 'утро (6-11)';
    else if (w.hour >= 11 && w.hour < 16) slot = 'день (11-16)';
    else if (w.hour >= 16 && w.hour < 21) slot = 'вечер (16-21)';
    else slot = 'ночь (21-6)';

    slots[slot].volumes.push(w.volume);
    slots[slot].count++;
  }

  // Find slot with highest average volume
  let bestSlot = '';
  let bestAvg = 0;
  let preferredSlot = '';
  let maxCount = 0;

  for (const [slot, data] of Object.entries(slots)) {
    if (data.count === 0) continue;
    const avg = data.volumes.reduce((a, b) => a + b, 0) / data.volumes.length;
    if (avg > bestAvg) {
      bestAvg = avg;
      bestSlot = slot;
    }
    if (data.count > maxCount) {
      maxCount = data.count;
      preferredSlot = slot;
    }
  }

  if (!bestSlot) return '';

  const lines: string[] = [];
  lines.push(`🏆 Лучшие результаты: ${bestSlot} (ср. объём ${Math.round(bestAvg)} кг)`);

  if (preferredSlot !== bestSlot && maxCount > 2) {
    lines.push(`📅 Обычно тренируется: ${preferredSlot} (${maxCount} раз)`);
    lines.push(`💡 Попробуй перенести тренировки на ${bestSlot} — объём там выше`);
  }

  return `\n\n## ⏰ ВРЕМЯ ТРЕНИРОВОК
${lines.join('\n')}
→ Учитывай при планировании расписания.`;
}

// ─── Block 60: Smart Deload Programming ─────────────────────────────────────
// Generate specific deload parameters when deload is recommended

function generateDeloadProgram(
  shouldDeload: boolean,
  lastWorkoutVolume: number,
  lastWorkoutExercises: Array<{ exercise: { name: string }; sets: Array<{ weight: number | null; reps: number | null }> }>,
  userGoal: string | null,
): string {
  if (!shouldDeload || lastWorkoutExercises.length === 0) return '';

  // Deload strategy depends on goal
  let volumeReduction: number;
  let intensityReduction: number;
  let strategy: string;

  if (userGoal === 'STRENGTH') {
    // Strength: keep intensity, reduce volume
    volumeReduction = 0.4; // 40% less sets
    intensityReduction = 0.1; // 10% less weight
    strategy = 'Сохраняем веса, снижаем объём (меньше подходов)';
  } else if (userGoal === 'MUSCLE_GAIN') {
    // Hypertrophy: reduce both moderately
    volumeReduction = 0.3;
    intensityReduction = 0.2;
    strategy = 'Снижаем веса на 20%, убираем 1-2 подхода в каждом упражнении';
  } else {
    // General: reduce everything
    volumeReduction = 0.5;
    intensityReduction = 0.3;
    strategy = 'Лёгкая неделя: 50% объёма, 70% рабочих весов';
  }

  const deloadExercises = lastWorkoutExercises.slice(0, 4).map((e) => {
    const maxWeight = Math.max(...e.sets.map((s) => s.weight || 0));
    const deloadWeight = Math.round((maxWeight * (1 - intensityReduction)) / 2.5) * 2.5; // round to 2.5kg
    const maxReps = Math.max(...e.sets.map((s) => s.reps || 0));
    const deloadSets = Math.max(2, Math.round(e.sets.length * (1 - volumeReduction)));

    return `- ${e.exercise.name}: ${deloadSets}×${maxReps} @ ${deloadWeight} кг`;
  });

  return `\n\n## 🧘 ПРОГРАММА DELOAD НЕДЕЛИ
Стратегия: ${strategy}
Пример deload тренировки:
${deloadExercises.join('\n')}
→ Предложи эту программу если пользователь спрашивает о deload или когда система рекомендует разгрузку.`;
}

// ─── Block 61: Water Intake Tracker ─────────────────────────────────────────
// Estimate daily water needs and remind about hydration

function buildHydrationAdvice(
  userWeightKg: number | null,
  userGoal: string | null,
  todayWorkout: boolean,
  todayMealsCount: number,
): string {
  if (!userWeightKg) return '';

  // Base: 30-35ml per kg body weight
  const baseWater = Math.round(userWeightKg * 33);
  let totalWater = baseWater;
  const notes: string[] = [];

  // Training day: +500-750ml
  if (todayWorkout) {
    totalWater += 600;
    notes.push('+600мл за тренировку');
  }

  // Goal-specific
  if (userGoal === 'WEIGHT_LOSS') {
    totalWater += 300;
    notes.push('+300мл для метаболизма (похудение)');
  } else if (userGoal === 'MUSCLE_GAIN') {
    totalWater += 400;
    notes.push('+400мл для синтеза белка (набор)');
  }

  // Season (summer = more water)
  const month = new Date().getMonth();
  if (month >= 5 && month <= 8) {
    totalWater += 400;
    notes.push('+400мл (лето, жара)');
  }

  const liters = (totalWater / 1000).toFixed(1);

  return `\n\n## 💧 ГИДРАТАЦИЯ
Рекомендуемый объём: ${liters} л/день (${totalWater} мл)
${notes.length > 0 ? `Расчёт: базовые ${baseWater}мл, ${notes.join(', ')}` : ''}
${todayMealsCount < 3 ? '⚠️ Мало приёмов пищи сегодня — не забывай пить между едой' : ''}
→ Напоминай о воде когда обсуждаешь питание или тренировки.`;
}

// ─── Block 62: Injury Risk Predictor ────────────────────────────────────────
// Flag risky training patterns before injury occurs

function predictInjuryRisks(
  fatigueRatio: number,
  fatigueStatus: string,
  muscleRecovery: MuscleRecoveryStatus[],
  overloadData: Array<{ exercise: string; status: string }>,
  recentWorkouts: Array<{ durationMinutes: number | null; completedAt: Date | null }>,
): string {
  const risks: string[] = [];

  // Risk 1: High ACWR ratio
  if (fatigueRatio > 1.5) {
    risks.push('🔴 ACWR > 1.5 — резкий скачок нагрузки, высокий риск травмы. Рекомендуй снизить объём.');
  } else if (fatigueRatio > 1.3) {
    risks.push('🟡 ACWR 1.3-1.5 — зона риска. Не увеличивай нагрузку дальше.');
  }

  // Risk 2: Training recovering muscles
  const notRecovered = muscleRecovery.filter((m) => m.status === 'fresh' || (m.status === 'recovering' && m.hoursSinceTraining < 24));
  if (notRecovered.length > 0) {
    risks.push(`🟡 Недовосстановленные мышцы: ${notRecovered.map((m) => m.muscle).join(', ')} — не нагружай их сегодня`);
  }

  // Risk 3: Consecutive heavy days without rest
  const completed = recentWorkouts
    .filter((w) => w.completedAt)
    .map((w) => new Date(w.completedAt!))
    .sort((a, b) => b.getTime() - a.getTime());

  if (completed.length >= 5) {
    // Check if last 5 workouts were within 5 days
    const daySpan = (completed[0].getTime() - completed[4].getTime()) / (1000 * 60 * 60 * 24);
    if (daySpan <= 5) {
      risks.push('🟠 5 тренировок за 5 дней — нет дней отдыха. Рекомендуй день восстановления.');
    }
  }

  // Risk 4: Long workouts without deload
  const longWorkouts = recentWorkouts.filter((w) => (w.durationMinutes || 0) > 120);
  if (longWorkouts.length >= 3) {
    risks.push('🟡 Регулярные тренировки >2ч — повышенный риск перетренированности и травм суставов');
  }

  if (risks.length === 0) return '';

  return `\n\n## ⚠️ РИСКИ ТРАВМ
${risks.join('\n')}
→ ПРИОРИТЕТНО: предупреди пользователя о рисках. Безопасность важнее прогресса.`;
}

// ─── Block 63: PR Prediction ────────────────────────────────────────────────
// Estimate when user will hit their next PR based on progression rate

function predictNextPR(
  overloadData: Array<{ exercise: string; status: string; lastWeights: number[]; suggestion: string }>,
): string {
  if (overloadData.length === 0) return '';

  const predictions: string[] = [];

  for (const ex of overloadData) {
    if (ex.status !== 'progressing' || ex.lastWeights.length < 3) continue;

    // Calculate weekly weight progression rate
    const weights = ex.lastWeights;
    const weeklyGain = (weights[weights.length - 1] - weights[0]) / Math.max(weights.length - 1, 1);

    if (weeklyGain <= 0) continue;

    const currentMax = weights[weights.length - 1];
    // Predict next milestone (round up to next 5kg)
    const nextMilestone = Math.ceil(currentMax / 5) * 5;
    if (nextMilestone <= currentMax) continue;

    const weeksToMilestone = Math.ceil((nextMilestone - currentMax) / weeklyGain);

    if (weeksToMilestone <= 8) {
      predictions.push(`📈 ${ex.exercise}: текущий макс ~${currentMax}кг → ${nextMilestone}кг через ~${weeksToMilestone} ${weeksToMilestone === 1 ? 'неделю' : weeksToMilestone < 5 ? 'недели' : 'недель'}`);
    }
  }

  if (predictions.length === 0) return '';

  return `\n\n## 🎯 ПРОГНОЗ РЕКОРДОВ
${predictions.slice(0, 3).join('\n')}
→ Мотивируй: «До нового рекорда осталось совсем немного!»`;
}

// ─── Block 64: Workout Duration Optimizer ───────────────────────────────────
// Detect time waste patterns and suggest efficiency improvements

function optimizeWorkoutDuration(
  recentWorkouts: Array<{
    durationMinutes: number | null;
    totalVolume: number | null;
    exercises: Array<{ sets: Array<{ completed: boolean }> }>;
  }>,
  userGoal: string | null,
): string {
  const completed = recentWorkouts.filter((w) => w.durationMinutes && w.durationMinutes > 0);
  if (completed.length < 3) return '';

  const avgDuration = completed.reduce((s, w) => s + (w.durationMinutes || 0), 0) / completed.length;
  const avgVolume = completed.reduce((s, w) => s + (w.totalVolume || 0), 0) / completed.length;

  // Volume per minute (efficiency metric)
  const efficiency = avgVolume / Math.max(avgDuration, 1);

  const suggestions: string[] = [];

  // Too long workouts
  if (avgDuration > 90 && userGoal !== 'STRENGTH') {
    suggestions.push(`⏱️ Средняя тренировка: ${Math.round(avgDuration)} мин — можно оптимизировать до 60-75 мин`);
    suggestions.push('💡 Совет: суперсеты антагонистов (грудь+спина), сокращение отдыха между лёгкими подходами');
  }

  // Low efficiency (low volume for time spent)
  if (efficiency < 50 && avgDuration > 45) {
    suggestions.push('📉 Низкая плотность тренировки — много времени, мало объёма');
    suggestions.push('💡 Совет: меньше пауз между подходами, убери лишние упражнения, фокус на базовые');
  }

  // Very short workouts
  if (avgDuration < 30 && userGoal !== 'WEIGHT_LOSS') {
    suggestions.push(`⚡ Средняя тренировка всего ${Math.round(avgDuration)} мин — возможно недостаточно объёма для прогресса`);
  }

  // Increasing duration trend
  if (completed.length >= 4) {
    const recent2 = completed.slice(0, 2).reduce((s, w) => s + (w.durationMinutes || 0), 0) / 2;
    const older2 = completed.slice(-2).reduce((s, w) => s + (w.durationMinutes || 0), 0) / 2;
    if (recent2 > older2 * 1.3) {
      suggestions.push('📈 Длительность тренировок растёт — убедись что это оправданный объём, а не затянутый отдых');
    }
  }

  if (suggestions.length === 0) return '';

  return `\n\n## ⚡ ЭФФЕКТИВНОСТЬ ТРЕНИРОВОК
${suggestions.join('\n')}
→ Помоги оптимизировать время в зале без потери качества.`;
}

// ─── Block 65: Seasonal Training Advisor ────────────────────────────────────
// Adjust training and nutrition advice for season, weather, and daylight

function getSeasonalAdvice(): string {
  const month = new Date().getMonth(); // 0-11
  const lines: string[] = [];

  if (month >= 11 || month <= 1) {
    // Зима (декабрь-февраль)
    lines.push('❄️ Зима: больше времени на разминку (10-15 мин), мышцы холоднее');
    lines.push('🥤 Витамин D: обязателен 2000-4000 МЕ/день (солнца почти нет)');
    lines.push('🍲 Увеличь калорийность на 5-10% — организм тратит энергию на терморегуляцию');
    lines.push('💡 Мотивация может падать из-за короткого светового дня — это нормально');
  } else if (month >= 2 && month <= 4) {
    // Весна (март-май)
    lines.push('🌱 Весна: хорошее время начать «сушку» к лету');
    lines.push('🏃 Добавь outdoor кардио — бег, велосипед (улучшает настроение после зимы)');
    lines.push('💊 Продолжай витамин D до мая (дефицит после зимы)');
  } else if (month >= 5 && month <= 7) {
    // Лето (июнь-август)
    lines.push('☀️ Лето: пей больше воды (+500мл в жару), электролиты при длительных тренировках');
    lines.push('🕐 Тренируйся утром или вечером — избегай пиковой жары (12-16)');
    lines.push('🥗 Лёгкая еда перед тренировкой, больше фруктов и овощей');
  } else {
    // Осень (сентябрь-ноябрь)
    lines.push('🍂 Осень: идеальное время для набора массы (межсезонье)');
    lines.push('🏋️ Увеличивай рабочие веса — прохладная погода, хороший аппетит');
    lines.push('😷 Укрепляй иммунитет: цинк, витамин C, достаточный сон');
  }

  return `\n\n## 🗓️ СЕЗОННЫЕ РЕКОМЕНДАЦИИ
${lines.slice(0, 3).join('\n')}
→ Учитывай при составлении программ и советах по питанию.`;
}

// ─── Block 66: Multi-Goal Conflict Detector ─────────────────────────────────
// Warn when user's stated goals conflict with their actual behavior

function detectGoalConflicts(
  userGoal: string | null,
  bodyWeightTrend: 'up' | 'down' | 'stable' | null,
  avgCalories: number | null,
  trainingFocus: 'strength' | 'hypertrophy' | 'cardio' | 'mixed' | null,
): string {
  if (!userGoal) return '';

  const conflicts: string[] = [];

  if (userGoal === 'WEIGHT_LOSS') {
    if (bodyWeightTrend === 'up') {
      conflicts.push('⚠️ Цель: похудение, но вес растёт. Проверь дефицит калорий — возможно, слишком много калорий.');
    }
    if (avgCalories && avgCalories > 2500) {
      conflicts.push('⚠️ Цель: похудение, но среднее потребление ~' + Math.round(avgCalories) + ' ккал — многовато для дефицита.');
    }
    if (trainingFocus === 'strength') {
      conflicts.push('💡 Цель: похудение, но фокус на силу. Добавь кардио и увеличь объём (больше повторений, меньше отдых).');
    }
  }

  if (userGoal === 'MUSCLE_GAIN') {
    if (bodyWeightTrend === 'down') {
      conflicts.push('⚠️ Цель: набор массы, но вес снижается. Увеличь калорийность на 300-500 ккал.');
    }
    if (avgCalories && avgCalories < 1800) {
      conflicts.push('⚠️ Цель: набор массы, но среднее ~' + Math.round(avgCalories) + ' ккал — слишком мало для роста.');
    }
    if (trainingFocus === 'cardio') {
      conflicts.push('💡 Цель: набор массы, но много кардио. Фокусируйся на силовых, кардио — 2-3 раза в неделю по 20 мин.');
    }
  }

  if (userGoal === 'STRENGTH') {
    if (trainingFocus === 'hypertrophy') {
      conflicts.push('💡 Цель: сила, но тренировки в стиле гипертрофии (10-15 повторений). Переходи на 3-6 повторений с тяжёлыми весами.');
    }
  }

  if (conflicts.length === 0) return '';

  return `\n\n## 🎯 КОНФЛИКТЫ ЦЕЛИ И ДЕЙСТВИЙ
${conflicts.join('\n')}
→ Деликатно укажи на противоречия и предложи конкретные корректировки.`;
}

// ─── Block 67: Workout Density Calculator ───────────────────────────────────
// Volume per minute — key metric for training quality

function calculateWorkoutDensity(
  recentWorkouts: Array<{
    name: string;
    totalVolume: number | null;
    durationMinutes: number | null;
  }>,
): string {
  const valid = recentWorkouts
    .filter((w) => w.totalVolume && w.totalVolume > 0 && w.durationMinutes && w.durationMinutes > 0)
    .map((w) => ({
      name: w.name,
      density: (w.totalVolume || 0) / (w.durationMinutes || 1),
      volume: w.totalVolume || 0,
      duration: w.durationMinutes || 0,
    }));

  if (valid.length < 2) return '';

  const avgDensity = valid.reduce((s, w) => s + w.density, 0) / valid.length;
  const best = valid.reduce((a, b) => (a.density > b.density ? a : b));
  const worst = valid.reduce((a, b) => (a.density < b.density ? a : b));

  // Trend
  let trend = '';
  if (valid.length >= 4) {
    const recent = valid.slice(0, 2).reduce((s, w) => s + w.density, 0) / 2;
    const older = valid.slice(-2).reduce((s, w) => s + w.density, 0) / 2;
    if (recent > older * 1.1) trend = '📈 Плотность растёт — ты работаешь эффективнее!';
    else if (recent < older * 0.85) trend = '📉 Плотность падает — больше пауз или легче веса.';
  }

  return `\n\n## 📐 ПЛОТНОСТЬ ТРЕНИРОВОК
Средняя: ${Math.round(avgDensity)} кг/мин
Лучшая: "${best.name}" (${Math.round(best.density)} кг/мин)
${worst.name !== best.name ? `Слабая: "${worst.name}" (${Math.round(worst.density)} кг/мин)` : ''}
${trend}
→ Чем выше плотность (при сохранении техники) — тем эффективнее тренировка.`;
}

// ─── Block 68: Personalized Rep Range Advisor ───────────────────────────────
// Optimal rep ranges based on goal + experience + current phase

function getRepRangeAdvice(
  userGoal: string | null,
  trainingAge: number,
  currentPhase: string,
): string {
  if (!userGoal) return '';

  interface RepRange { main: string; auxiliary: string; rationale: string }
  const ranges: Record<string, RepRange> = {
    STRENGTH: {
      main: '3-5 повторений @ 85-95% 1RM',
      auxiliary: '6-8 повторений @ 70-80% 1RM',
      rationale: 'Тяжёлые подходы развивают максимальную силу (нейромышечная адаптация)',
    },
    MUSCLE_GAIN: {
      main: '8-12 повторений @ 65-75% 1RM',
      auxiliary: '12-15 повторений @ 55-65% 1RM',
      rationale: 'Средний диапазон оптимален для гипертрофии (механическое напряжение + метаболический стресс)',
    },
    WEIGHT_LOSS: {
      main: '12-15 повторений @ 55-65% 1RM',
      auxiliary: '15-20 повторений @ 45-55% 1RM',
      rationale: 'Высокий объём + короткий отдых = больше калорий сожжено + сохранение мышц',
    },
    ENDURANCE: {
      main: '15-25 повторений @ 40-55% 1RM',
      auxiliary: '25-30+ повторений или время под нагрузкой',
      rationale: 'Длительная нагрузка развивает мышечную выносливость и капиллярную сеть',
    },
    GENERAL_FITNESS: {
      main: '8-15 повторений @ 60-75% 1RM',
      auxiliary: '6-8 тяжёлых + 15-20 лёгких (чередование)',
      rationale: 'Широкий диапазон для всестороннего развития',
    },
  };

  const range = ranges[userGoal] || ranges.GENERAL_FITNESS;

  // Adjust for training age
  let modifier = '';
  if (trainingAge < 1) {
    modifier = '\n💡 Для новичка: начинай с верхней границы повторений (больше практики техники).';
  } else if (trainingAge > 5) {
    modifier = '\n💡 Для опытных: чередуй диапазоны (DUP — разная нагрузка в разные дни недели).';
  }

  // Adjust for phase
  let phaseNote = '';
  if (currentPhase === 'deload') {
    phaseNote = '\n⚠️ Сейчас деload: работай на 50-60% от обычных весов, фокус на технику.';
  } else if (currentPhase === 'peaking') {
    phaseNote = '\n⚡ Фаза peaking: снижай повторения, увеличивай вес. 1-3 повторения для тестов.';
  }

  return `\n\n## 🔢 РЕКОМЕНДУЕМЫЕ ДИАПАЗОНЫ ПОВТОРЕНИЙ
Основные: ${range.main}
Вспомогательные: ${range.auxiliary}
Почему: ${range.rationale}${modifier}${phaseNote}
→ Используй при составлении программ и обсуждении подходов.`;
}

// ─── Block 69: Training Split Recommender ───────────────────────────────────
// Suggest optimal split based on frequency, recovery, and goal

function recommendSplit(
  daysPerWeek: number,
  userGoal: string | null,
  trainingAge: number,
  muscleRecovery: MuscleRecoveryStatus[],
): string {
  if (daysPerWeek <= 0) return '';

  interface SplitOption { name: string; description: string; schedule: string }
  const recommendations: SplitOption[] = [];

  if (daysPerWeek <= 2) {
    recommendations.push({
      name: 'Full Body',
      description: '2 тренировки всё тело — оптимально при низкой частоте',
      schedule: 'Пн: Full Body A, Чт: Full Body B',
    });
  } else if (daysPerWeek === 3) {
    if (trainingAge < 2) {
      recommendations.push({
        name: 'Full Body 3x',
        description: 'Новичкам лучше полное тело 3 раза — больше практики базовых движений',
        schedule: 'Пн: Full Body A, Ср: Full Body B, Пт: Full Body C',
      });
    } else {
      recommendations.push({
        name: 'Push/Pull/Legs',
        description: 'Классический PPL — каждая мышечная группа 1 раз в неделю',
        schedule: 'Пн: Push, Ср: Pull, Пт: Legs',
      });
    }
  } else if (daysPerWeek === 4) {
    recommendations.push({
      name: 'Upper/Lower',
      description: 'Верх/Низ 2x — каждая группа 2 раза в неделю, хороший баланс',
      schedule: 'Пн: Upper, Вт: Lower, Чт: Upper, Пт: Lower',
    });
    if (userGoal === 'STRENGTH') {
      recommendations.push({
        name: '5/3/1',
        description: 'Wendler 5/3/1 — проверенная силовая программа с авторегуляцией',
        schedule: 'Пн: Жим, Вт: Присед, Чт: Жим стоя, Пт: Тяга',
      });
    }
  } else if (daysPerWeek >= 5) {
    recommendations.push({
      name: 'PPL 2x',
      description: 'Push/Pull/Legs дважды в неделю — высокая частота, быстрый прогресс',
      schedule: 'Пн: Push, Вт: Pull, Ср: Legs, Чт: отдых, Пт: Push, Сб: Pull, Вс: Legs',
    });
    if (userGoal === 'MUSCLE_GAIN') {
      recommendations.push({
        name: 'Bro Split',
        description: 'Классический сплит по мышечным группам — максимальный объём на группу',
        schedule: 'Пн: Грудь, Вт: Спина, Ср: Плечи, Чт: Ноги, Пт: Руки',
      });
    }
  }

  if (recommendations.length === 0) return '';

  const rec = recommendations[0]; // primary recommendation
  return `\n\n## 📋 РЕКОМЕНДУЕМЫЙ СПЛИТ
${rec.name}: ${rec.description}
Расписание: ${rec.schedule}
${recommendations.length > 1 ? `Альтернатива: ${recommendations[1].name} — ${recommendations[1].description}` : ''}
→ Предлагай при создании или обсуждении программы.`;
}

// ─── Block 70: AI Response Language Enforcer ────────────────────────────────
// Strengthen Russian-only response guarantee in system prompt

function buildLanguageEnforcer(recentMessages: Array<{ role: string; content: string }>): string {
  // Check if recent AI responses contained English
  const recentAI = recentMessages.filter((m) => m.role === 'assistant').slice(-3);
  const hasEnglish = recentAI.some((m) => {
    const englishWords = (m.content.match(/\b[a-zA-Z]{4,}\b/g) || []).filter(
      (w) => !['push', 'pull', 'legs', 'full', 'body', 'upper', 'lower', 'rpe', 'rir',
        'bcaa', 'eaa', 'met', 'epoc', 'dup', 'amrap', 'emom', 'hiit', 'drop', 'super',
        'set', 'rep', 'max', 'bmi', 'acwr', 'deload', 'rest', 'pause', 'split'].includes(w.toLowerCase())
    );
    return englishWords.length > 5;
  });

  if (hasEnglish) {
    return '\n\n⚠️ КРИТИЧНО: В предыдущих ответах замечен английский текст. СТРОГО отвечай ТОЛЬКО на русском языке. Англоязычные термины (RPE, AMRAP, HIIT, etc.) допустимы, но предложения и объяснения — ТОЛЬКО по-русски.';
  }

  return '';
}

// ─── Block 71: Weak Point Identifier ────────────────────────────────────────
// Find muscle groups that lag behind based on volume distribution

function identifyWeakPoints(
  recentWorkouts: Array<{
    exercises: Array<{
      exercise: { primaryMuscles: string[] };
      sets: Array<{ weight: number | null; reps: number | null; completed: boolean }>;
    }>;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  // Calculate volume per muscle group
  const muscleVolume: Record<string, number> = {};
  const muscleFrequency: Record<string, number> = {};

  for (const w of recentWorkouts) {
    const musclesThisWorkout = new Set<string>();
    for (const ex of w.exercises) {
      for (const muscle of ex.exercise.primaryMuscles) {
        const vol = ex.sets
          .filter((s) => s.completed)
          .reduce((sum, s) => sum + (s.weight || 0) * (s.reps || 0), 0);
        muscleVolume[muscle] = (muscleVolume[muscle] || 0) + vol;
        musclesThisWorkout.add(muscle);
      }
    }
    for (const m of musclesThisWorkout) {
      muscleFrequency[m] = (muscleFrequency[m] || 0) + 1;
    }
  }

  if (Object.keys(muscleVolume).length < 3) return '';

  const totalVolume = Object.values(muscleVolume).reduce((a, b) => a + b, 0);
  const avgVolume = totalVolume / Object.keys(muscleVolume).length;

  // Find significantly undertrained muscles
  const weak = Object.entries(muscleVolume)
    .filter(([, vol]) => vol < avgVolume * 0.4)
    .map(([muscle, vol]) => ({
      muscle,
      volume: vol,
      pct: Math.round((vol / avgVolume) * 100),
      frequency: muscleFrequency[muscle] || 0,
    }))
    .sort((a, b) => a.pct - b.pct);

  // Find important neglected muscle groups
  const importantMuscles = ['quadriceps', 'hamstrings', 'glutes', 'back', 'chest', 'shoulders'];
  const neglected = importantMuscles.filter((m) => !muscleVolume[m] || muscleVolume[m] < avgVolume * 0.2);

  const lines: string[] = [];

  if (weak.length > 0) {
    lines.push(`📉 Отстающие мышцы: ${weak.slice(0, 3).map((w) => `${w.muscle} (${w.pct}% от среднего)`).join(', ')}`);
  }

  if (neglected.length > 0) {
    const muscleNames: Record<string, string> = {
      quadriceps: 'квадрицепсы', hamstrings: 'задняя поверхность бедра', glutes: 'ягодицы',
      back: 'спина', chest: 'грудь', shoulders: 'плечи',
    };
    lines.push(`⚠️ Почти не тренируются: ${neglected.map((m) => muscleNames[m] || m).join(', ')}`);
  }

  if (lines.length === 0) return '';

  return `\n\n## 🔍 СЛАБЫЕ МЕСТА
${lines.join('\n')}
→ Предложи добавить упражнения на отстающие группы мышц. Баланс важен для здоровья и эстетики.`;
}

// ─── Block 72: Rest Day Activity Advisor ────────────────────────────────────
// Suggest active recovery activities for rest days

function buildRestDayAdvice(
  daysSinceLastWorkout: number | null,
  recoveryScore: number,
  muscleRecovery: MuscleRecoveryStatus[],
): string {
  if (daysSinceLastWorkout === null || daysSinceLastWorkout < 1) return '';

  const activities: string[] = [];

  if (recoveryScore < 50) {
    // Low recovery — very light activity
    activities.push('🧘 Лёгкая растяжка (15-20 мин) — снимает напряжение без нагрузки');
    activities.push('🚶 Прогулка (20-30 мин) — улучшает кровообращение и восстановление');
    activities.push('🧊 Контрастный душ — горячий 1мин / холодный 30сек × 3-4 цикла');
  } else if (recoveryScore < 75) {
    // Moderate recovery — light activity
    activities.push('🏊 Лёгкое плавание (20-30 мин) — разгружает суставы, улучшает кровоток');
    activities.push('🧘 Йога или мобильность (20-30 мин) — растяжка и стабилизация');
    activities.push('🚴 Лёгкое кардио (велосипед/ходьба) — пульс 100-120 уд/мин');
  } else {
    // Good recovery — moderate activity ok
    activities.push('🏃 Лёгкий бег или быстрая ходьба (30-40 мин)');
    activities.push('🏊 Плавание или подвижные игры');
    activities.push('🧘 Глубокая растяжка + foam rolling (20 мин)');
  }

  // Specific muscle advice
  const sorest = muscleRecovery.filter((m) => m.status === 'recovering').slice(0, 2);
  if (sorest.length > 0) {
    activities.push(`💆 Foam rolling / массаж: ${sorest.map((s) => s.muscle).join(', ')} (особенно нуждаются)`);
  }

  return `\n\n## 🌿 ДЕНЬ ОТДЫХА (${daysSinceLastWorkout}д без тренировки)
${activities.slice(0, 3).join('\n')}
→ Предлагай если пользователь спрашивает чем заняться в день отдыха.`;
}

// ─── Block 73: Protein Timing Optimizer ─────────────────────────────────────
// Distribute protein intake optimally across meals

function optimizeProteinTiming(
  todayMeals: Array<{ type: string; totalProtein: number; createdAt: Date }>,
  userWeightKg: number | null,
  userGoal: string | null,
  hasWorkoutToday: boolean,
): string {
  if (!userWeightKg) return '';

  // Target protein per day
  let proteinTarget: number;
  if (userGoal === 'MUSCLE_GAIN') proteinTarget = userWeightKg * 2.0;
  else if (userGoal === 'WEIGHT_LOSS') proteinTarget = userWeightKg * 2.2; // higher to preserve muscle
  else if (userGoal === 'STRENGTH') proteinTarget = userWeightKg * 1.8;
  else proteinTarget = userWeightKg * 1.6;

  const totalProtein = todayMeals.reduce((sum, m) => sum + m.totalProtein, 0);
  const remaining = Math.max(0, proteinTarget - totalProtein);

  const lines: string[] = [];
  lines.push(`Цель: ${Math.round(proteinTarget)}г белка/день (${(proteinTarget / userWeightKg).toFixed(1)}г/кг)`);
  lines.push(`Сегодня: ${Math.round(totalProtein)}г из ${Math.round(proteinTarget)}г (${Math.round((totalProtein / proteinTarget) * 100)}%)`);

  if (remaining > 40) {
    const mealsLeft = hasWorkoutToday ? 3 : 2; // assume more meals on training day
    const perMeal = Math.round(remaining / mealsLeft);
    lines.push(`📌 Осталось добрать: ${Math.round(remaining)}г (~${perMeal}г на оставшиеся приёмы)`);
  }

  // Timing advice
  if (hasWorkoutToday) {
    lines.push('⏰ Пост-тренировочный приём (30-60мин после): 30-40г быстрого белка (сывороточный протеин, яйца)');
  }

  // Check meal distribution
  if (todayMeals.length >= 2) {
    const maxProtein = Math.max(...todayMeals.map((m) => m.totalProtein));
    const minProtein = Math.min(...todayMeals.map((m) => m.totalProtein));
    if (maxProtein > minProtein * 3 && minProtein < 20) {
      lines.push('⚠️ Белок распределён неравномерно — старайся 25-40г в каждом приёме');
    }
  }

  return `\n\n## 🥩 БЕЛОК СЕГОДНЯ
${lines.join('\n')}
→ Упоминай при обсуждении питания. Помоги добрать белок к концу дня.`;
}

// ─── Block 74: Workout Naming Intelligence ──────────────────────────────────
// Help AI suggest meaningful workout names from exercise composition

function suggestWorkoutName(
  exercises: Array<{ exercise: { primaryMuscles: string[]; category: string } }>,
): string {
  if (exercises.length === 0) return '';

  const allMuscles = exercises.flatMap((e) => e.exercise.primaryMuscles);
  const muscleCount: Record<string, number> = {};
  for (const m of allMuscles) muscleCount[m] = (muscleCount[m] || 0) + 1;

  const topMuscles = Object.entries(muscleCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([m]) => m);

  const muscleNames: Record<string, string> = {
    chest: 'Грудь', back: 'Спина', shoulders: 'Плечи', biceps: 'Бицепс', triceps: 'Трицепс',
    quadriceps: 'Квадрицепс', hamstrings: 'Бицепс бедра', glutes: 'Ягодицы', calves: 'Икры',
    abs: 'Пресс', lats: 'Широчайшие', traps: 'Трапеция', forearms: 'Предплечья',
  };

  // Detect common splits
  const hasChest = topMuscles.includes('chest');
  const hasBack = topMuscles.includes('back') || topMuscles.includes('lats');
  const hasLegs = topMuscles.includes('quadriceps') || topMuscles.includes('hamstrings') || topMuscles.includes('glutes');
  const hasShoulders = topMuscles.includes('shoulders');
  const categories = exercises.map((e) => e.exercise.category);
  const hasCardio = categories.includes('cardio');

  let suggestion = '';
  if (hasChest && hasShoulders && topMuscles.includes('triceps')) suggestion = 'Push (Грудь + Плечи + Трицепс)';
  else if (hasBack && topMuscles.includes('biceps')) suggestion = 'Pull (Спина + Бицепс)';
  else if (hasLegs && !hasChest && !hasBack) suggestion = 'Ноги';
  else if (hasChest && !hasLegs) suggestion = `Верх (${topMuscles.slice(0, 2).map((m) => muscleNames[m] || m).join(' + ')})`;
  else if (hasCardio) suggestion = 'Кардио + Функционал';
  else suggestion = topMuscles.slice(0, 2).map((m) => muscleNames[m] || m).join(' + ');

  return `\n\nСовет для названия тренировки: «${suggestion}»`;
}

// ─── Block 75: Confidence Calibration ───────────────────────────────────────
// Adjust AI certainty based on available data volume

function calibrateConfidence(
  totalWorkouts: number,
  bodyWeightEntries: number,
  mealEntries: number,
  memoryCount: number,
): string {
  let dataLevel: 'minimal' | 'low' | 'moderate' | 'good' | 'rich';
  const score = totalWorkouts * 3 + bodyWeightEntries * 2 + mealEntries + memoryCount * 2;

  if (score < 10) dataLevel = 'minimal';
  else if (score < 30) dataLevel = 'low';
  else if (score < 80) dataLevel = 'moderate';
  else if (score < 200) dataLevel = 'good';
  else dataLevel = 'rich';

  const directives: Record<string, string> = {
    minimal: '⚠️ ДАННЫХ ОЧЕНЬ МАЛО. Будь осторожен с рекомендациями. Задавай больше вопросов. Используй общие советы, а не персонализированные. Не делай выводов о прогрессе.',
    low: '⚠️ Мало данных. Рекомендации ориентировочные. Объясняй что для точных советов нужно больше тренировок/замеров.',
    moderate: 'Средний объём данных. Можно давать персонализированные советы, но отмечай неопределённость в прогнозах.',
    good: 'Хороший объём данных. Персонализация надёжна. Можно делать уверенные рекомендации по программам и питанию.',
    rich: 'Богатая история данных. Максимальная персонализация. Можно выявлять тренды, паттерны, давать точные рекомендации.',
  };

  return `\n\n## 📊 УРОВЕНЬ ДАННЫХ: ${dataLevel.toUpperCase()} (${score} баллов)
${directives[dataLevel]}`;
}

// ─── Block 76: Volume Landmark Tracker ──────────────────────────────────────
// Track cumulative lifetime volume milestones (tonnage achievements)

function trackVolumeLandmarks(
  recentWorkouts: Array<{
    exercises: Array<{
      sets: Array<{ weight: number | null; reps: number | null; completed: boolean }>;
    }>;
    completedAt: Date | null;
  }>,
  totalWorkoutsEver: number,
): string {
  if (recentWorkouts.length === 0) return '';

  // Estimate lifetime volume from recent data
  const recentVolumes = recentWorkouts.map((w) =>
    w.exercises.reduce((sum, ex) =>
      sum + ex.sets.filter((s) => s.completed).reduce((s, set) => s + (set.weight || 0) * (set.reps || 0), 0), 0),
  );
  const avgVolume = recentVolumes.reduce((a, b) => a + b, 0) / recentVolumes.length;
  const estimatedLifetimeVolume = Math.round(avgVolume * totalWorkoutsEver);

  // Tonnage milestones
  const milestones = [10_000, 25_000, 50_000, 100_000, 250_000, 500_000, 1_000_000];
  const nextMilestone = milestones.find((m) => m > estimatedLifetimeVolume);
  const lastMilestone = milestones.filter((m) => m <= estimatedLifetimeVolume).pop();

  const lines: string[] = [];
  lines.push(`Примерный общий тоннаж: ~${(estimatedLifetimeVolume / 1000).toFixed(0)} тонн`);

  if (lastMilestone) {
    lines.push(`✅ Достигнут рубеж: ${(lastMilestone / 1000).toFixed(0)} тонн`);
  }

  if (nextMilestone) {
    const remaining = nextMilestone - estimatedLifetimeVolume;
    const workoutsToGo = avgVolume > 0 ? Math.ceil(remaining / avgVolume) : 0;
    lines.push(`🎯 Следующий рубеж: ${(nextMilestone / 1000).toFixed(0)} тонн (осталось ~${workoutsToGo} тренировок)`);
  }

  // Session volume trend
  if (recentVolumes.length >= 3) {
    const recent3 = recentVolumes.slice(0, 3);
    const older = recentVolumes.slice(3);
    if (older.length > 0) {
      const recentAvg = recent3.reduce((a, b) => a + b, 0) / recent3.length;
      const olderAvg = older.reduce((a, b) => a + b, 0) / older.length;
      const changePct = Math.round(((recentAvg - olderAvg) / olderAvg) * 100);
      if (Math.abs(changePct) > 10) {
        lines.push(`${changePct > 0 ? '📈' : '📉'} Тоннаж за тренировку: ${changePct > 0 ? '+' : ''}${changePct}% vs предыдущие`);
      }
    }
  }

  return `\n\n## 🏋️ ТОННАЖ
${lines.join('\n')}`;
}

// ─── Block 77: Workout Consistency Analyzer ─────────────────────────────────
// Analyze training schedule consistency and suggest improvements

function analyzeConsistency(
  recentWorkouts: Array<{ completedAt: Date | null }>,
  plannedDaysPerWeek: number,
): string {
  const completed = recentWorkouts.filter((w) => w.completedAt).map((w) => new Date(w.completedAt!));
  if (completed.length < 3) return '';

  // Analyze gaps between workouts
  const gaps: number[] = [];
  for (let i = 0; i < completed.length - 1; i++) {
    const gap = Math.round((completed[i].getTime() - completed[i + 1].getTime()) / (1000 * 60 * 60 * 24));
    gaps.push(gap);
  }

  const avgGap = gaps.reduce((a, b) => a + b, 0) / gaps.length;
  const maxGap = Math.max(...gaps);
  const minGap = Math.min(...gaps);
  const gapVariance = gaps.reduce((sum, g) => sum + Math.pow(g - avgGap, 2), 0) / gaps.length;
  const consistency = Math.max(0, 100 - Math.round(Math.sqrt(gapVariance) * 20));

  const lines: string[] = [];
  lines.push(`Средний интервал между тренировками: ${avgGap.toFixed(1)} дней`);
  lines.push(`Стабильность расписания: ${consistency}%`);

  if (plannedDaysPerWeek > 0) {
    const idealGap = 7 / plannedDaysPerWeek;
    if (avgGap > idealGap * 1.5) {
      lines.push(`⚠️ Тренируешься реже плана (${plannedDaysPerWeek} дн/нед → идеал: каждые ${idealGap.toFixed(1)} дн)`);
    }
  }

  if (maxGap > 7) {
    lines.push(`⚠️ Был перерыв ${maxGap} дней — стабильность важнее интенсивности`);
  }

  // Day-of-week preference
  const dayCount: Record<number, number> = {};
  for (const d of completed) {
    const day = d.getDay();
    dayCount[day] = (dayCount[day] || 0) + 1;
  }
  const dayNames = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'];
  const favoriteDays = Object.entries(dayCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 2)
    .map(([day]) => dayNames[Number(day)]);
  if (favoriteDays.length > 0) {
    lines.push(`Любимые дни: ${favoriteDays.join(', ')}`);
  }

  return `\n\n## 📅 СТАБИЛЬНОСТЬ ТРЕНИРОВОК
${lines.join('\n')}
→ Используй при планировании расписания и рекомендациях по частоте.`;
}

// ─── Block 78: Exercise Tempo Advisor ───────────────────────────────────────
// Suggest tempo prescriptions based on goal, experience, and exercise type

function buildTempoAdvice(
  userGoal: string | null,
  fitnessLevel: string | null,
  currentExercises: Array<{ exercise: { category: string; type: string; name: string } }>,
): string {
  if (!userGoal || currentExercises.length === 0) return '';

  // Tempo format: eccentric-pause-concentric-pause (seconds)
  interface TempoRec {
    tempo: string;
    explanation: string;
  }

  const tempoByGoal: Record<string, TempoRec> = {
    MUSCLE_GAIN: { tempo: '3-1-2-0', explanation: '3с негатив, 1с пауза, 2с подъём — максимальное время под нагрузкой' },
    STRENGTH: { tempo: '2-1-1-0', explanation: '2с негатив, 1с пауза, 1с взрыв — контроль + мощность' },
    WEIGHT_LOSS: { tempo: '2-0-2-0', explanation: '2с/2с — умеренный темп для жиросжигания с контролем' },
    ENDURANCE: { tempo: '2-0-2-0', explanation: '2с/2с — ритмичный, без пауз, поддерживаем ЧСС' },
    GENERAL_FITNESS: { tempo: '2-1-2-0', explanation: '2с/2с с паузой — безопасный контролируемый темп' },
  };

  const rec = tempoByGoal[userGoal] || tempoByGoal['GENERAL_FITNESS'];

  const lines: string[] = [];
  lines.push(`Рекомендуемый темп: ${rec.tempo} (${rec.explanation})`);

  // Beginner override
  if (fitnessLevel === 'BEGINNER') {
    lines.push('💡 Для новичков: фокус на контроле. Не спеши. Считай до 3 на негативной фазе.');
  }

  // Exercise-specific tips
  const hasCompound = currentExercises.some((e) => ['barbell', 'dumbbell'].includes(e.exercise.type));
  const hasIsolation = currentExercises.some((e) => e.exercise.type === 'machine' || e.exercise.type === 'cable');

  if (hasCompound) {
    lines.push('🏋️ Базовые: контролируй негатив, не бросай штангу');
  }
  if (hasIsolation) {
    lines.push('🔧 Изоляция: можно замедлить ещё сильнее (4-1-3-1) для лучшего пампинга');
  }

  return `\n\n## ⏱️ ТЕМП ВЫПОЛНЕНИЯ
${lines.join('\n')}
→ Упоминай при обсуждении техники и эффективности тренировок.`;
}

// ─── Block 79: Muscle Balance Score ─────────────────────────────────────────
// Calculate push/pull/legs balance ratio

function calculateMuscleBalance(
  recentWorkouts: Array<{
    exercises: Array<{
      exercise: { primaryMuscles: string[] };
      sets: Array<{ completed: boolean }>;
    }>;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  // Classify muscles into movement patterns
  const pushMuscles = new Set(['chest', 'shoulders', 'triceps']);
  const pullMuscles = new Set(['back', 'lats', 'biceps', 'traps', 'forearms']);
  const legMuscles = new Set(['quadriceps', 'hamstrings', 'glutes', 'calves', 'adductors', 'abductors']);

  let pushSets = 0, pullSets = 0, legSets = 0;

  for (const w of recentWorkouts) {
    for (const ex of w.exercises) {
      const completedSets = ex.sets.filter((s) => s.completed).length;
      const primary = ex.exercise.primaryMuscles[0];
      if (!primary) continue;
      if (pushMuscles.has(primary)) pushSets += completedSets;
      else if (pullMuscles.has(primary)) pullSets += completedSets;
      else if (legMuscles.has(primary)) legSets += completedSets;
    }
  }

  const total = pushSets + pullSets + legSets;
  if (total < 10) return '';

  const pushPct = Math.round((pushSets / total) * 100);
  const pullPct = Math.round((pullSets / total) * 100);
  const legPct = Math.round((legSets / total) * 100);

  // Ideal ratio roughly 30:35:35 (more pulling for posture)
  const issues: string[] = [];
  if (pushPct > pullPct + 10) issues.push('больше тяг (горизонт. + вертик.) для баланса плечевого пояса');
  if (legPct < 20) issues.push('увеличить объём на ноги (≥30% от общего)');
  if (pullPct < 20) issues.push('добавить тяговые движения для здоровья спины');

  const lines: string[] = [];
  lines.push(`Push ${pushPct}% : Pull ${pullPct}% : Legs ${legPct}% (подходов: ${pushSets}/${pullSets}/${legSets})`);

  if (issues.length > 0) {
    lines.push(`⚠️ Рекомендации: ${issues.join('; ')}`);
  } else {
    lines.push('✅ Баланс Push/Pull/Legs в норме');
  }

  return `\n\n## ⚖️ БАЛАНС ДВИЖЕНИЙ
${lines.join('\n')}
→ Учитывай при составлении и корректировке программ.`;
}

// ─── Block 80: Micro-Cycle Phase Detector ───────────────────────────────────
// Detect if user is in accumulation, intensification, or peaking phase

function detectTrainingPhase(
  recentWorkouts: Array<{
    exercises: Array<{
      sets: Array<{ weight: number | null; reps: number | null; completed: boolean; type: string }>;
    }>;
    completedAt: Date | null;
  }>,
): string {
  if (recentWorkouts.length < 3) return '';

  // Analyze last 3 workouts
  const sessions = recentWorkouts.slice(0, 3).map((w) => {
    const allSets = w.exercises.flatMap((e) =>
      e.sets.filter((s) => s.completed && s.weight && s.reps && s.type !== 'warmup'),
    );
    const avgReps = allSets.length > 0
      ? allSets.reduce((sum, s) => sum + (s.reps || 0), 0) / allSets.length
      : 0;
    const avgWeight = allSets.length > 0
      ? allSets.reduce((sum, s) => sum + (s.weight || 0), 0) / allSets.length
      : 0;
    const totalSets = allSets.length;
    return { avgReps, avgWeight, totalSets };
  });

  const currentAvgReps = sessions[0].avgReps;
  const currentAvgWeight = sessions[0].avgWeight;
  const currentVolume = sessions[0].totalSets;

  // Determine phase
  let phase: string;
  let description: string;
  let advice: string;

  if (currentAvgReps >= 10 && currentVolume >= 15) {
    phase = 'НАКОПЛЕНИЕ (Accumulation)';
    description = 'Высокий объём, умеренные веса — строим базу для будущего прогресса';
    advice = 'Фокус на технике и объёме. Не гонись за весами. Достаточно еды и сна.';
  } else if (currentAvgReps >= 5 && currentAvgReps < 10) {
    phase = 'ИНТЕНСИФИКАЦИЯ (Intensification)';
    description = 'Средние повторы, растущие веса — переход к силовой работе';
    advice = 'Увеличивай веса постепенно. Сократи объём если нужно. Отдых между подходами 2-3 мин.';
  } else if (currentAvgReps < 5 && currentAvgWeight > 0) {
    phase = 'ПИК (Peaking)';
    description = 'Низкие повторы, тяжёлые веса — реализация силового потенциала';
    advice = 'Максимальное восстановление. Лёгкое кардио. Не добавляй лишний объём.';
  } else {
    phase = 'ОБЩАЯ ПОДГОТОВКА';
    description = 'Смешанный тренинг без выраженной фазы';
    advice = 'Определи приоритет: объём или сила. Периодизация ускоряет прогресс.';
  }

  // Trend detection
  const repsTrend = sessions.length >= 2
    ? sessions[0].avgReps < sessions[sessions.length - 1].avgReps ? 'снижение повторов ↓' : 'рост повторов ↑'
    : '';
  const weightTrend = sessions.length >= 2
    ? sessions[0].avgWeight > sessions[sessions.length - 1].avgWeight ? 'рост весов ↑' : ''
    : '';

  const trends = [repsTrend, weightTrend].filter(Boolean);

  return `\n\n## 🔄 ТРЕНИРОВОЧНАЯ ФАЗА
Фаза: ${phase}
${description}
${trends.length > 0 ? `Тренд: ${trends.join(', ')}` : ''}
💡 ${advice}`;
}

// ─── Block 81: Caloric Surplus/Deficit Estimator ────────────────────────────
// Based on goal, estimate if user is eating enough or too much

function estimateCaloricBalance(
  todayMeals: Array<{ totalCalories: number }>,
  userWeightKg: number | null,
  userGoal: string | null,
  hasWorkoutToday: boolean,
  userGender: string | null,
  userAge: number | null,
): string {
  if (!userWeightKg || todayMeals.length === 0) return '';

  // Estimate BMR using Mifflin-St Jeor
  let bmr: number;
  if (userGender === 'MALE') {
    bmr = 10 * userWeightKg + 6.25 * 175 - 5 * (userAge || 25) + 5; // assume 175cm if unknown
  } else {
    bmr = 10 * userWeightKg + 6.25 * 165 - 5 * (userAge || 25) - 161;
  }

  // Activity multiplier
  const activityMultiplier = hasWorkoutToday ? 1.55 : 1.3;
  const tdee = Math.round(bmr * activityMultiplier);

  // Target based on goal
  let targetCalories: number;
  let targetLabel: string;
  if (userGoal === 'WEIGHT_LOSS') {
    targetCalories = tdee - 400;
    targetLabel = 'дефицит ~400 ккал';
  } else if (userGoal === 'MUSCLE_GAIN') {
    targetCalories = tdee + 300;
    targetLabel = 'профицит ~300 ккал';
  } else {
    targetCalories = tdee;
    targetLabel = 'поддержание';
  }

  const consumed = Math.round(todayMeals.reduce((sum, m) => sum + m.totalCalories, 0));
  const balance = consumed - targetCalories;

  const lines: string[] = [];
  lines.push(`Расчётный TDEE: ~${tdee} ккал (${targetLabel})`);
  lines.push(`Цель: ~${targetCalories} ккал | Съедено: ${consumed} ккал`);

  if (balance > 200) {
    lines.push(`⚠️ Превышение на ~${balance} ккал${userGoal === 'WEIGHT_LOSS' ? ' — может замедлить похудение' : ''}`);
  } else if (balance < -500 && userGoal !== 'WEIGHT_LOSS') {
    lines.push(`⚠️ Недоедание ~${Math.abs(balance)} ккал — может ухудшить восстановление`);
  }

  return `\n\n## 🔥 КАЛОРИЙНЫЙ БАЛАНС
${lines.join('\n')}
→ Используй при обсуждении питания. Рекомендуй корректировки если баланс не соответствует цели.`;
}

// ─── Block 82: Joint Health Monitor ─────────────────────────────────────────
// Flag exercises that may stress joints based on user's health restrictions

function monitorJointHealth(
  healthRestrictions: Array<{ bodyPart: string; description: string; severity: string }>,
  scheduledExercises: Array<{ exercise: { name: string; primaryMuscles: string[]; type: string } }>,
): string {
  if (healthRestrictions.length === 0 || scheduledExercises.length === 0) return '';

  // Map body parts to potentially problematic exercises
  const riskMap: Record<string, string[]> = {
    'колено': ['quadriceps', 'hamstrings', 'glutes', 'calves'],
    'knee': ['quadriceps', 'hamstrings', 'glutes', 'calves'],
    'плечо': ['shoulders', 'chest'],
    'shoulder': ['shoulders', 'chest'],
    'спина': ['back', 'lats', 'lower_back'],
    'back': ['back', 'lats', 'lower_back'],
    'поясница': ['lower_back', 'glutes', 'hamstrings'],
    'lower_back': ['lower_back', 'glutes', 'hamstrings'],
    'запястье': ['forearms', 'biceps', 'triceps'],
    'wrist': ['forearms', 'biceps', 'triceps'],
    'локоть': ['biceps', 'triceps', 'forearms'],
    'elbow': ['biceps', 'triceps', 'forearms'],
  };

  const warnings: string[] = [];

  for (const restriction of healthRestrictions) {
    const bodyPart = restriction.bodyPart.toLowerCase();
    const riskyMuscles = riskMap[bodyPart] || [];
    if (riskyMuscles.length === 0) continue;

    const riskyExercises = scheduledExercises.filter((ex) =>
      ex.exercise.primaryMuscles.some((m) => riskyMuscles.includes(m)),
    );

    if (riskyExercises.length > 0) {
      const severity = restriction.severity === 'severe' ? '🔴' : restriction.severity === 'moderate' ? '🟡' : '🟢';
      warnings.push(
        `${severity} ${restriction.bodyPart}: ${restriction.description} (${restriction.severity}) — потенциально задействованы: ${riskyExercises.map((e) => e.exercise.name).join(', ')}`,
      );
    }
  }

  if (warnings.length === 0) return '';

  return `\n\n## 🩺 ЗДОРОВЬЕ СУСТАВОВ
${warnings.join('\n')}
→ ОБЯЗАТЕЛЬНО предупреди пользователя. Предложи замену или модификацию (меньший вес, другой хват, машина вместо свободных весов).`;
}

// ─── Block 83: Progressive Overload Suggestions ─────────────────────────────
// Suggest specific weight/rep increases for each exercise based on recent performance

function suggestProgressiveOverload(
  recentWorkouts: Array<{
    exercises: Array<{
      exercise: { name: string; id: string; type: string };
      sets: Array<{ weight: number | null; reps: number | null; completed: boolean; type: string }>;
    }>;
    completedAt: Date | null;
  }>,
  userGoal: string | null,
): string {
  if (recentWorkouts.length < 2) return '';

  // Group by exercise across workouts
  const exerciseData: Record<string, {
    name: string;
    type: string;
    sessions: Array<{ maxWeight: number; maxReps: number; allCompleted: boolean }>;
  }> = {};

  for (const w of recentWorkouts) {
    for (const ex of w.exercises) {
      const workingSets = ex.sets.filter((s) => s.completed && s.type !== 'warmup' && (s.weight || 0) > 0);
      if (workingSets.length === 0) continue;

      if (!exerciseData[ex.exercise.id]) {
        exerciseData[ex.exercise.id] = { name: ex.exercise.name, type: ex.exercise.type, sessions: [] };
      }

      const maxWeight = Math.max(...workingSets.map((s) => s.weight || 0));
      const maxReps = Math.max(...workingSets.map((s) => s.reps || 0));
      const allCompleted = workingSets.every((s) => s.completed);

      exerciseData[ex.exercise.id].sessions.push({ maxWeight, maxReps, allCompleted });
    }
  }

  const suggestions: string[] = [];

  for (const { name, type, sessions } of Object.values(exerciseData)) {
    if (sessions.length < 2) continue;

    const latest = sessions[0];
    const previous = sessions[1];

    // If all sets completed at same weight for 2+ sessions → suggest increase
    if (latest.maxWeight === previous.maxWeight && latest.allCompleted && previous.allCompleted) {
      let increment: number;
      if (type === 'barbell') increment = 2.5;
      else if (type === 'dumbbell') increment = 2;
      else increment = 5; // machines usually have larger increments

      const newWeight = latest.maxWeight + increment;

      // Goal-based strategy
      if (userGoal === 'STRENGTH') {
        suggestions.push(`${name}: ${latest.maxWeight}→${newWeight} кг (все подходы выполнены 2 раза подряд)`);
      } else if (userGoal === 'MUSCLE_GAIN') {
        // Could also suggest adding reps first
        if (latest.maxReps < 12) {
          suggestions.push(`${name}: сначала доведи до 12 повторений, затем ${latest.maxWeight}→${newWeight} кг`);
        } else {
          suggestions.push(`${name}: ${latest.maxWeight}→${newWeight} кг (12+ повторений достигнуто)`);
        }
      } else {
        suggestions.push(`${name}: можно попробовать ${newWeight} кг (+${increment})`);
      }
    }
  }

  if (suggestions.length === 0) return '';

  return `\n\n## 📈 ПРОГРЕССИЯ НАГРУЗКИ
Готовы к увеличению:
${suggestions.slice(0, 5).map((s) => `- ${s}`).join('\n')}
→ Предложи эти увеличения когда пользователь обсуждает тренировку или прогресс.`;
}

// ─── Block 84: Sleep & Recovery Window Estimator ────────────────────────────
// Estimate optimal sleep and recovery based on training load

function estimateRecoveryWindow(
  recentWorkouts: Array<{
    exercises: Array<{
      sets: Array<{ weight: number | null; reps: number | null; completed: boolean }>;
    }>;
    durationMinutes: number | null;
    completedAt: Date | null;
  }>,
  userGoal: string | null,
): string {
  if (recentWorkouts.length === 0) return '';

  const lastWorkout = recentWorkouts[0];
  if (!lastWorkout.completedAt) return '';

  // Calculate workout intensity score
  const totalVolume = lastWorkout.exercises.reduce((sum, ex) =>
    sum + ex.sets.filter((s) => s.completed).reduce((s, set) => s + (set.weight || 0) * (set.reps || 0), 0), 0);
  const totalSets = lastWorkout.exercises.reduce((sum, ex) =>
    sum + ex.sets.filter((s) => s.completed).length, 0);
  const duration = lastWorkout.durationMinutes || 60;

  // Intensity score: volume per minute
  const intensity = totalVolume / duration;

  // Recovery time estimation
  let recoveryHours: number;
  if (intensity > 150) recoveryHours = 72; // very heavy
  else if (intensity > 100) recoveryHours = 48; // heavy
  else if (intensity > 50) recoveryHours = 36; // moderate
  else recoveryHours = 24; // light

  const hoursAgo = Math.round((Date.now() - new Date(lastWorkout.completedAt).getTime()) / (1000 * 60 * 60));
  const recoveryPct = Math.min(100, Math.round((hoursAgo / recoveryHours) * 100));

  const lines: string[] = [];
  lines.push(`Последняя тренировка: ${hoursAgo}ч назад (${totalSets} подходов, ${Math.round(totalVolume)} кг объём)`);
  lines.push(`Восстановление: ${recoveryPct}% (расчётное время: ${recoveryHours}ч)`);

  // Sleep recommendation
  const sleepHours = intensity > 100 ? '8-9' : '7-8';
  lines.push(`💤 Рекомендуемый сон: ${sleepHours} часов для полного восстановления`);

  if (recoveryPct < 70) {
    lines.push('⚠️ Полное восстановление ещё не наступило. Если тренировка сегодня — работай на другие мышечные группы.');
  }

  return `\n\n## 😴 ОКНО ВОССТАНОВЛЕНИЯ
${lines.join('\n')}`;
}

// ─── Block 85: Personalized Warm-Up Set Calculator ──────────────────────────
// Calculate warm-up ramp-up sets for the main working weight

function calculateWarmupSets(
  scheduledExercises: Array<{
    exercise: { name: string; type: string; primaryMuscles: string[] };
    sets: Array<{ weight: number | null; reps: number | null }>;
  }>,
): string {
  if (scheduledExercises.length === 0) return '';

  // Only for compound barbell/dumbbell exercises
  const compoundExercises = scheduledExercises.filter((ex) =>
    ['barbell', 'dumbbell'].includes(ex.exercise.type) &&
    ex.sets.some((s) => (s.weight || 0) >= 40),
  );

  if (compoundExercises.length === 0) return '';

  const warmups: string[] = [];

  for (const ex of compoundExercises.slice(0, 3)) {
    const workingWeight = Math.max(...ex.sets.map((s) => s.weight || 0));
    if (workingWeight < 40) continue;

    // Ramp-up protocol
    const sets: string[] = [];
    if (workingWeight >= 100) {
      sets.push(`Пустой гриф × 10`);
      sets.push(`${Math.round(workingWeight * 0.4)} кг × 8`);
      sets.push(`${Math.round(workingWeight * 0.6)} кг × 5`);
      sets.push(`${Math.round(workingWeight * 0.8)} кг × 3`);
    } else if (workingWeight >= 60) {
      sets.push(`Пустой гриф × 10`);
      sets.push(`${Math.round(workingWeight * 0.5)} кг × 8`);
      sets.push(`${Math.round(workingWeight * 0.75)} кг × 5`);
    } else {
      sets.push(`${Math.round(workingWeight * 0.5)} кг × 10`);
      sets.push(`${Math.round(workingWeight * 0.75)} кг × 5`);
    }

    warmups.push(`${ex.exercise.name} (рабочий: ${workingWeight} кг): ${sets.join(' → ')}`);
  }

  if (warmups.length === 0) return '';

  return `\n\n## 🔥 РАЗМИНОЧНЫЕ ПОДХОДЫ
${warmups.join('\n')}
→ Предложи разминку если пользователь спрашивает с чего начать или как разогреться.`;
}

// ─── Block 86: Workout Pacing Advisor ───────────────────────────────────────
// Analyze rest times between sets and suggest pacing improvements

function analyzeWorkoutPacing(
  recentWorkouts: Array<{
    exercises: Array<{
      restSeconds: number;
      sets: Array<{ completed: boolean }>;
    }>;
    durationMinutes: number | null;
    completedAt: Date | null;
    startedAt: Date | null;
  }>,
  userGoal: string | null,
): string {
  if (recentWorkouts.length === 0) return '';

  const lastWorkout = recentWorkouts[0];
  if (!lastWorkout.startedAt || !lastWorkout.completedAt) return '';

  const actualDuration = lastWorkout.durationMinutes ||
    Math.round((new Date(lastWorkout.completedAt).getTime() - new Date(lastWorkout.startedAt).getTime()) / 60000);

  const totalSets = lastWorkout.exercises.reduce((sum, ex) =>
    sum + ex.sets.filter((s) => s.completed).length, 0);
  const avgRestConfigured = lastWorkout.exercises.length > 0
    ? Math.round(lastWorkout.exercises.reduce((sum, ex) => sum + ex.restSeconds, 0) / lastWorkout.exercises.length)
    : 90;

  // Estimate time spent exercising vs resting
  const estimatedWorkTime = totalSets * 0.5; // ~30sec per set
  const estimatedRestTime = actualDuration - estimatedWorkTime;
  const restPercentage = actualDuration > 0 ? Math.round((estimatedRestTime / actualDuration) * 100) : 0;

  const lines: string[] = [];

  // Goal-specific rest recommendations
  const idealRest: Record<string, { range: string; seconds: number }> = {
    STRENGTH: { range: '3-5 мин', seconds: 240 },
    MUSCLE_GAIN: { range: '60-90 сек', seconds: 75 },
    WEIGHT_LOSS: { range: '30-60 сек', seconds: 45 },
    ENDURANCE: { range: '30-45 сек', seconds: 38 },
    GENERAL_FITNESS: { range: '60-120 сек', seconds: 90 },
  };
  const ideal = idealRest[userGoal || 'GENERAL_FITNESS'] || idealRest['GENERAL_FITNESS'];

  lines.push(`Тренировка: ${actualDuration} мин, ${totalSets} подходов, отдых ~${restPercentage}% времени`);
  lines.push(`Настроенный отдых: ${avgRestConfigured} сек | Рекомендуемый для цели: ${ideal.range}`);

  if (avgRestConfigured > ideal.seconds * 1.5) {
    lines.push(`⚠️ Отдых слишком длинный для цели «${userGoal}». Сократи до ${ideal.range}.`);
  } else if (avgRestConfigured < ideal.seconds * 0.5 && userGoal === 'STRENGTH') {
    lines.push(`⚠️ Для силовой работы отдыхай дольше (${ideal.range}). Короткий отдых снижает силу.`);
  }

  return `\n\n## ⏱️ ТЕМП ТРЕНИРОВКИ
${lines.join('\n')}`;
}

// ─── Block 87: Exercise Substitution Intelligence ───────────────────────────
// When user can't do an exercise, suggest smart alternatives

